(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["gn"] = {"ui":{"skip":"Eho ñe'ẽme","back":"← Eho jey AI-gile-pe","lang.button":"Ñe'ẽ: {name}","lang.dialog":"Eiporavo peteĩ ñe'ẽ","lang.search":"Eheka ñe'ẽ","lang.none":"Ndaipóri ñe'ẽ ojojogua","lang.notYet":"{name} ndojehaijeporekái gueteri","theme.aria":"Emoambue tema: tesaí, pytũmby térã hũ","theme.toLight":"Eho tesaípe","theme.toDark":"Eho pytũmbýpe","theme.toBlack":"Eho tema hũme (hũ añete, porã pantalla OLED-pe g̃uarã)","words.underline":"Emoĩ línea ko'ã ñe'ẽ guýpe ko kuatiaroguépe","words.underlineHelp":"Emoĩ mouse térã epoko peteĩ ñe'ẽ punteado ári rehecha haguã mba'épa he'ise.","words.col.todo":"Tarjeta oiporavopyre ko'ágã guarã: atyha oñepyrũta ko'ã rehe upéi.","words.col.doing":"Peteĩ IA omba'apo ko tarjeta ári ko'ágã.","words.col.review":"Peteĩ IA opa pe tembiapo; ambue ohecha ndéve oguahẽ mboyve.","words.col.verify":"Nde rembiapo: eprueba ha emombe'u omba'apóramo.","words.col.team":"Nde notakuéra térã nde mbohovái, ohaʼarõva atyha ojagarra haguã.","words.col.done":"Opamba ha ojeguerohory.","index.title":"AI-gile: nde atyha AI, peteĩ tabla-pe","index.description":"AI-gile ha'e peteĩ kanban tabla atyha AI-pe oñehaíva código. Omba'apo reiko aja ereke; nde reñemoĩ ñemoĩ michĩ rehe: mba'e eikuaa haguã, eprueba haguã ha eaceptar haguã.","hero.logoAlt":"AI-gile tabla ta'anga","hero.h1.html":"Nde atyha AI, peteĩ&nbsp;tabla-pe.","hero.alpha":"🐣 Pre-alfa mboty","hero.alphaTitle":"Ojepyrũ gueteri ha ndopáiva: aguyje eprueba haguã!","hero.lede":"Omopu'ã reiko aja ereke. Reñepyrũ jey peteĩ ñemoĩ michĩ ndive: sa'i porandu, sa'i mba'e eprueba haguã, peteĩ térã mokõi diamante pytãngy. Eikutu, eaceptar, ha eho jey nde kafe-pe.","dl.windows":"Windows aplicación","dl.browser":"Eipuru nde navegador-pe","dl.messenger":"📱 Messenger nde pumbyry g̃uarã","dl.soon":"Jepémo ndaikatúi","dl.notify":"🔔 Eñemomarandu aipo ojeipe'a vove","dl.notifySmall":"Alfa térã beta","hero.secondary":"Agile, ha katu atyha ndoikotevẽi kafe-ñepyrũ pukukue. (Péicha jepe ojapo.)","pitch.h2":"AI-gile oñe'ẽ hetaiterei ndive","pitch.lede":"Eiporavo pukukue, peteĩ ñe'ẽ guive 144 peve. Peteĩteĩ pukukue ha'e mba'e ojehaíva hese guarã. Emongu'e pe sliders térã eipuru flecha.","pitch.rangeLabel":"Pukukue ñe'ẽme","pitch.dice":"🎲 ambue versión","pitch.words.one":"{n} ñe'ẽ","pitch.words.other":"{n} ñe'ẽ","pitch.letters.one":"{n} tai","pitch.letters.other":"{n} tai","pitch.chars.one":"{n} tai","pitch.chars.other":"{n} tai","count.line.html.one":"{n} kuatia tabla-pe ko'ágã","count.line.html.other":"{n} kuatia tabla-pe ko'ágã","people.humans.html.one":"👥 {n} yvypóra","people.humans.html.other":"👥 {n} yvypóra","people.agents.html.one":"🤖 {n} pytyvõhára","people.agents.html.other":"🤖 {n} pytyvõhára","people.working.html.one":"⚡ {n} omba'apo ko'ágã","people.working.html.other":"⚡ {n} omba'apo ko'ágã","pre.title":"AI-gile: oñemopu'ã peteĩ mba'e","pre.description":"Ko'ápe oñemopu'ã peteĩ mba'e. Peteĩ tabla, AI atyha ojapohápe umi ejeruréva, ha nembo'e hikuái ojapo aja. Ko'ágã peve, pre-alfa mboty angirũnguéra ndive.","pre.h1":"Ko'ápe oñemopu'ã peteĩ mba'e. 🤫","pre.line":"Peteĩ tabla, AI atyha ojapohápe umi ejeruréva, ha nembo'e hikuái ojapo aja. Ko'ágã peve, pre-alfa mboty angirũnguéra ndive.","pre.btn":"🔔 Eñemomarandu aipo ojeipe'a vove","pre.peek":"Vidrio rapykuéri: tabla añetegua, hekoveve. Opaite kuatia ha'e peteĩ líña sa'ýva.","pre.peekFake":"Vidrio rapykuéri: péicha ojehecha peteĩ tabla omba'apo aja.","pre.night":"🌙 Pyhare ñangarekoha oisãmbyhy · 😴 yvypóra opytu'u","features.aria":"Mba'épa ojapo","f.pile.h":"Peteĩ ñemoĩ ndéve guarã","f.pile.html":"<b>Ndéve</b> oñongatu opa mba'e ndépe oha'arõva, opa tembiapo-pe: porandu, mba'e eprueba haguã, tembiapo ikatúva ojapo ha'e añoite. Nde fila he'i mba'e oúva ha mboy ára.","f.sleep.h":"Atyha omba'apóva reiko aja ereke","f.sleep.p":"Peteĩteĩ tembiapo oguereko peteĩ líder ha peteĩ atyha agente AI. Eñe'ẽ peteĩ kuatia-pe ha atyha oñemoĩ, ojapo pe tembiapo ha ombohasa jey ndéve tapykuépe ikatúva omuña peteĩ tapicha kane'õva.","f.tester.h":"Peteĩ AI tester ohecha raẽ","f.tester.p":"Oĩ mboyve ndéve, peteĩ tester oho tapykuépe peteĩ kopia aplicación-pe ha ohechauka mba'e ohecha, peteĩ pantalla ta'angapy ndive. Ehecha pe ojeheróva ha eaceptar peteĩ kutu-pe.","f.proof.h":"Hechaukapy, ndaha'éi ñe'ẽme'ẽ","f.proof.p":"Peteĩteĩ ñemoĩ ohechauka mba'e ojoko'i: umi marandu, pe diff, umi pantalla ta'angapy. Ndereikotevẽi embojuruja opa aplicación ehecha haguã ojejapopáma.","f.chat.h":"Eñe'ẽ nde líder kuérape","f.chat.p":"Peteĩ rail Discord-icha: peteĩ ta'anga peteĩteĩ tembiapo-pe guarã, diamante pytãngy mba'e ndéve oikotevẽvape guarã. Emondo ñemoñe'ẽ peteĩ líder-pe; ha'e ombojoapy kuatia ha peteĩ plan-pe, peteĩ ✅ Go votõ ndive.","f.tidy.h":"Ombyaty ijehe","f.tidy.p":"Umi kuatia joapýva oñembyaty peteĩme, umi téra ñembyaíva oñemoĩporã, ha peteĩ token jehecha ohecha pe código opyta hesakã. Sa'ive mba'e ojeiko hendápe, sa'ive mba'e ñepensa.","f.private.h":"Nde mba'e, nde mba'e'oka-pe","f.private.li1":"Pe tabla omba'apo nde máquina-pe ha ombohovái ndéve añoite.","f.private.li2":"DM ñemigua tapicha pa'ũme oñemigua pyteguápe.","f.private.li3":"Ndaipóri cuenta, ndaipóri tracker, ndaipóri cookie.","f.lang.h":"Nde ñe'ẽme","f.lang.p":"Hetave 120 ñe'ẽ, holandés, galés ha japonés guive pirata, Yoda ha klingon peve, ha peteĩ ñemoambue pya'e inglés-pe tembiapo ñe'ẽ-rã.","f.service.h":"Peteĩ temiandu guive peteĩ servicio añetegua peve","f.service.p":"Remopu'ã peteĩ mba'e AI reheve tapichakuéra oiporúmava? Emarka servicio ramo ha tablero nepytyvõta reñangareko porã haguã: uptime jehecha, peteĩ kuatiaha estado opavavépe g̃uarã, incidente-kuéra mombe'u reheve, moambue oikotevẽva peteĩ Ñaha, backup ojehecháva ára ha ára. Pytyvõ nembo'e peteĩ teĩ py'õ reho aja.","msgr.h2":"AI-gile Messenger: nde atyha nde vosápe","msgr.p1":"Eñe'ẽ nde atyha AI ndive reipe'a'ỹre pe tabla. Eñemongeta nde líder kuéra ha nde angirũnguéra ndive, ha ehecha peteĩ kuatia prueba rape ha embohovái, opa mba'e nde pumbyrýgui.","msgr.p2":"Embojoaju haguã, eskanea peteĩ QR código nde tablape. Peteĩha jey? Peteĩ ñemongeta demo py'aporã ohechaukáta ndéve opa mba'e.","msgr.when":"Android raẽ, upéi peteĩ web versión pumbyry ha iPhone g̃uarã.","msgr.who":"Nde proyecto líder","msgr.b1":"Modo pytũ ñemyatyrõ oĩma. Reipotápa prueba rape?","msgr.b2":"Héẽ, ajerure!","msgr.b3":"1. Eipe'a Ñemoĩ. 2. Eiporavo Pytũ. Ojehecha porãpa?","tl.aria":"Ára tape ñe'ẽ ñepyrũ guive plan peve","tl.h2":"Ñepyrũ ñe'ẽ guive oúvape","tl.lede":"Árape ha aravopápe añete, nde zona horaria-pe. Ko árare guive ha'e plan, ndojepromeséiva árape.","tl.today":"Ko árape","tl.planned":"oñeplanea","tl.doing":"ojejapóva","tl.cards.one":"{n} kuatia","tl.cards.other":"{n} kuatia","join.h2":"Eñemoirũ","join.lede":"AI-gile oñemopu'ã peteĩ kuimba'e hendyva iñambuéva, oguerekóva AuDHD ha oñorairõva'ekue mbovymi jey iñakã resãi rehe, ha hetaiterei agente ipasiénsiavape. Ko'ágã ñemigua, peteĩ alfa mboty-pe angirũ ndive. Ndereipotái eprueba ojeipe'a vove?","join.btn":"Emoĩ ne interés","join.small":"Rehaíta ndéve email, ndaipóri hetave","footer.tag":"AI-gile. Ndaipóri tracker, ndaipóri cookie, ndaipóri kafe-ñepyrũ.","footer.licence":"Negocio licencia","footer.status":"Estado","footer.privacy":"Mba'épa ñañongatu","footer.thanks":"Henói ChilledChat rupive","form.sending":"Ojejapo…","form.failed":"Péva ndojapói: eha'ã jey upéi.","form.offline":"Ndaikatúi ojejuhu AI-gile: eha'ã jey upéi.","form.keep":"Ñaipuru kóva ñambohovái haguãnte ndéve, upéi ñamboguete. Ndaipóri tracker, ndaipóri cookie.","form.keepLink":"Mba'épa ñañongatu","interest.title":"AI-gile: emoñe'ẽ chéve ojeipe'a vove alfa","interest.description":"Eheja nde email ehendu haguã araka'e ojeipe'a AI-gile alfa mboty térã beta.","interest.h1":"🔔 Emoñe'ẽ chéve ojeipe'a vove","interest.lede":"AI-gile oĩ pre-alfa mboty-pe. Eheja nde email ha rehaíta peteĩ jey, oĩ vove ndéve guarã tenda.","interest.email":"Nde email","interest.which":"Mba'e prueba?","interest.alpha":"Alfa mboty: ojepyrũ, ipiru'ã, hetaiterei ñemoambue","interest.beta":"Beta: hekopete ave, upéi","interest.both":"Mokõive, mba'e oúva raẽ","interest.submit":"Eñemoĩ chéve lista-pe","interest.thanks":"Aguyje! Reime lista-pe.","licence.title":"AI-gile: negocio licencia","licence.description":"Eipuru AI-gile nde negocio-pe? Eñemoĩ peteĩ licencia negocio mba'e'ỹre.","licence.h1":"📜 Negocio licencia","licence.lede":"Eipuru AI-gile tembiapo-pe? Emombe'u chéve máva ha mba'e rejapo. Ojapo ramo porã, pe licencia ndaipóri hepyrã.","licence.company":"Empresa","licence.website":"Sitio web","licence.what":"Mba'e rejapo","licence.how":"Mba'éichapa omoherakuã yvy","licence.email":"Email","licence.submit":"Emoĩ","licence.thanks":"Aguyje! Ñamboguata ndéve email rupi.","status.title":"AI-gile estado","status.h1":"AI-gile estado","status.quiet":"Opa mba'e kirirĩ","status.intro":"AI-gile omba'apópa ko'ágã? Ko kuatiarogue ohecha sitio web, tabla ñemoherakuã, ñehenói ha descarga káda 5 minuto.","status.up":"Omba'apo (ombohovái {ms} ms-pe)","status.slow":"Ndombohováii ñehecha pahápe, oñeha'ã jey","status.down":"Oñembyai: ndombohováii umi mokõi ñehecha pahápe","status.svc.web":"Sitio web","status.svc.web.offers":"Ko sitio: mba'épa AI-gile, ha formulario interés rehegua","status.svc.boards":"Tabla ñemoherakuã","status.svc.boards.offers":"Tabla opavavépe guarã, marandu angirũnguéra apytépe ha invitación","status.svc.calls":"Ñehenói","status.svc.calls.offers":"Ñe'ẽ, video ha pantalla ñemoherakuã AI-gile-pe","status.svc.download":"Descarga","status.svc.download.offers":"Windows instalador ha invitación enlace","status.checking":"Ojehecha…","status.offline":"Ko'ágã ndaikatúi ojejuhu estado servicio (oha'ã jey)","status.updated":"oñembopyahu {ago}","status.justNow":"ko'ágã","status.min":"{n} min rembýpe","status.hours":"{n} h rembýpe","status.days":"{n} ára rembýpe","privacy.title":"AI-gile: mba'épa ñañongatu","privacy.h1":"Mba'épa ñañongatu","privacy.lede":"Mbykyhápe: nde remondóva ñandéve añoite, ha ndaha'éi are guarã.","privacy.only":"Nde remondóva ñandéve añoite: rehaíva formulario-pe, ne email ramo. Ndaipóri ambue mba'e nderehegua.","privacy.sealed":"Oñemboty porã ani haguã ñane servidor omoñe'ẽ: ne navegador-pe osẽ mboyve (navegador tujavévape, og̃uahẽ vove). Ñane tabla añoite ikatu oipe'a.","privacy.server":"Oñemboguete servidor-gui og̃uahẽ rire ñane tabla-pe. Oĩramo gueteri upépe 30 ára rire, oñemboguete avei.","privacy.board":"Ñañongatu ñane tabla-pe ñambohovái peve ndéve, upéi ñamboguete upégui avei.","privacy.none":"Ndaipóri tracker, ndaipóri cookie, ndaipóri analítica.","privacy.local":"Ne ñe'ẽ ha ne poravo tesakã térã pytũ opyta ne navegador-pe. Araka'eve noñemondói ñandéve.","privacy.ask":"Reipotápa oñemboguete pya'eve? Embohovái ñane email ha ere ñandéve.","live.h2":"Ehecha ojejapo aja, hekoveve","live.caption":"Opaite kuatia ojeñomi: ehecha tembiapo ra’anga, ndaha’éi ñe’ẽ.","live.watching.one":"hekoveve: {n} ohecha","live.watching.other":"hekoveve: {n} ohecha","live.last.now":"Pe kárta ipahaitéva oñemoĩ ko'ágã","live.last.min.one":"Pe kárta ipahaitéva oñemoĩ {n} min ohasaramóva","live.last.min.other":"Pe kárta ipahaitéva oñemoĩ {n} min ohasaramóva","live.last.hour.one":"Pe kárta ipahaitéva oñemoĩ {n} aravo ohasaramóva","live.last.hour.other":"Pe kárta ipahaitéva oñemoĩ {n} aravo ohasaramóva","live.last.day.one":"Pe kárta ipahaitéva oñemoĩ {n} ára ohasaramóva","live.last.day.other":"Pe kárta ipahaitéva oñemoĩ {n} ára ohasaramóva","live.offline":"Tablero hekoveve ojepytuʼu sa’i. Eju jey pya’e.","live.cols":"Backlog|Ojejapótava|Ojejapóva|Atyha ohecháva|Ndéve ehecha haguã test|Atyha pe|Ojejapopáma"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Ojeheja."]},{"n":2,"texts":["Kanban robot.","Agente, organizado.","Mba'e, ojapóva."]},{"n":3,"texts":["Kanban robot-pe guarã.","Ñemoñe'ẽ ojeapo.","Agente kanban, mba'e'ỹre."]},{"n":5,"texts":["Kanban tabla agente omoñeñandúva.","Nde rehai kuatia. Agente ojapo.","Mba'e'ỹre, local, probado, sa'i tavy."]},{"n":8,"texts":["Peteĩ kanban tabla mba'e'ỹre, agente AI omba'apoha.","Ehai peteĩ ñemoñe'ẽ. Agente ojapo. Nde eaceptar.","Agile peteĩ tapicha ha hetaiterei robot ipasiénsiavape guarã."]},{"n":13,"texts":["Peteĩ kanban tabla nde mba'e'oka-pe, agente AI oipyhy hendápe kuatia.","Ehai peteĩ ñemoñe'ẽ. Peteĩ atyha agente ojapo. Peteĩ tester ohecha.","Mba'e'ỹre, ndaipóri cuenta ni tracker: peteĩ tabla, sa'i robot, ha nde remandúva."]},{"n":21,"texts":["AI-gile ha'e peteĩ kanban tabla ñemba'apo agente AI código ojapóva ndive. Ha'ekuéra oipyhy kuatia; nde eprueba ha eaceptar.","Peteĩteĩ tembiapo oguereko peteĩ líder ha peteĩ atyha agente AI. Eñe'ẽ oimeraẽ kuatia-pe ha atyha oñepyrũ pya'e omba'apo.","Peteĩ tabla personal mba'e'ỹre omba'apóva nde mba'e'oka-pe. Umi omba'apóva ha'e robot ha'ekuéra. Ha nde ha'e pe he'íva heẽ, tapiaite."]},{"n":34,"texts":["Reñemoĩ ne ñemoñe'ẽ peteĩ tabla-pe. Peteĩ atyha agente AI ombojoapy ha ojapo hese mba'e omba'apóva, oprueba mba'e ojejapo ha ombohasa jey ndéve tapykuépe eha'ã haguã. Mba'eve ndojejapopái nde ere peve, tapiaite.","AI-gile ha'e peteĩ kanban tabla ógape ojejapóva, Rich ojapo heta ñepytyvõ ndive umi agente ha'e ko'ágã ombohováiva. Ndaipóri hepyrã, omba'apo nde mba'e'oka-pe, ha oñemoherakuã angirũ ndive, ndaha'éi ojehepyme'ẽ haguã.","Eñeimo'ã peteĩ kanban tabla tembiguáipe, columna Backlog guive Ojejapopáma peve, ha katu kuatia oipyhy agente AI. Omombe'u mba'e oho, oporandu ojepyta vove, ha oha'arõ tapiaite nde heẽ."]},{"n":55,"texts":["AI-gile ha'e peteĩ kanban tabla, ha pe atyha ojejapo agente AI-gui. Peteĩteĩ tembiapo oguereko peteĩ líder oplanéava pe tembiapo ha oipytyvõva ojapóva ha'e pe ojapo haguã. Peteĩ tembiapo oĩ vove hembýva, peteĩ AI tester oprueba ha ojapo peteĩ pantalla ta'angapy, upéi ohupyty nde ñemoĩ. Eaceptar ko mba'e, térã eñe'ẽ ha ojapo jey hikuái.","Ojepyrũ peteĩ tapicha rape ha'e ohecha haguã hetaiterei sesión código AI ndive peteĩ jey, ha upéi okakuaa peteĩ tabla añete. Omba'apo nde máquina-pe, ndoikotevẽi cuenta, ha ndaipóri tracker. Ndaipóri hepyrã angirũ-pe ha oikuaasevape. Avei ndopái gueteri, upévare eha'arõ mba'e ipiru'ã ha sorpresa sa'i, ha upéva ndaha'éi mba'eve.","Péicha añete, ndahasýi. Ndéve reikotevẽ gueteri ñemoñe'ẽ, ha reikotevẽ gueteri rehecha umi ojejapóva. AI-gile ojapo opa mba'e ko'ã mokõi mbytépe: oñongatu kuatia hekopete, omopu'ã pe agente hekopete reñe'ẽ vove kuatia-pe, ohechauka mba'e ojoko'i, ha ombyaty opa mba'e peteĩ ñemoĩ mbykýpe ndéve guarã. Péicha ndereikotevẽi reikuaa'ỹ mba'e oiko, ha rereko ne ñe'ẽ ipahápe."]},{"n":89,"texts":["AI-gile ha'e peteĩ kanban tabla mba'e'ỹre reipurúva nde mba'e'oka-pe. Tapicha rãngue, peteĩteĩ tembiapo oguereko peteĩ atyha agente AI: peteĩ líder ombojoapýva ne ñemoñe'ẽ kuatia ha plan-pe, ha oipytyvõva oipyhy kuatia ojejapo vaerã peteĩ tape rupi. Peteĩ mba'e oñemopu'ã vove, peteĩ AI tester oho prueba tapykuépe ha ohechauka ndéve mba'e ohecha. Upéi oha'arõ peteĩ ñemoĩ-pe hérava Ndéve. Eaceptar, térã eñe'ẽ ha atyha oha'ã jey. Mba'eve ndoguahẽi Ojejapopáma-pe nde'ỹre, mba'eveichagua. Péicha ndéve ndaipóri ñemondo'ỹ, ha ndaipóri sorpresa vai.","Oĩ mba'e ndereha'arõiva avei. Peteĩ pyhare ñangareko ombyaty columna Ojejapótava rehegua reiko aja ereke, oiporavóva kuatia ndoikotevẽiva nde mbohovái. Peteĩ token jepapa ohechauka mboy ojeporu umi agente ko ára ha ko arapokõindy-pe, ha No Token Mode he'i chupe kuéra ani ojepuru hetave. Ikatu reñemondo marandu nde angirũ kuérape, ha marandu ñemigua oñemigua pyteguápe. Pe tabla oñe'ẽ 120 ñe'ẽ rupi, holandés, flamenco, pirata ha klingon ndive. Mba'eve ndohepýi, ha avave ndoheka ombohepy nde-pe.","AI-gile ha'e peteĩ tembiapo michĩ personal, ndaha'éi empresa. Rich oipota ñangareko hetaiterei tembiapo código AI rehegua ndaikotevẽi haguã embojuruja opa aplicación ehecha haguã mba'e oikóva hese, upévare ha'e ha umi agente ojapo peteĩ tabla upepe guarã, ha upéi oiporu pe tabla ojapo haguã opa ambue hembýva. Oĩ pre-alfa mboty-pe, he'ise omba'apo, hetáva, sa'i angirũ-pe guarã. Ndaipóri páhina hepyrã, ndaipóri boletín ha ndaipóri plan kakuaa. Ojeporu ramo ndéve, ikatu reporandu eprueba haguã ojeipe'a vove sa'ive, ha ñande ñeha'ã."]},{"n":144,"texts":["AI-gile ha'e peteĩ kanban tabla peteĩ tapicha ha hetaiterei agente AI-pe guarã. Omba'apo nde mba'e'oka-pe ha ndaipóri hepyrã mba'eveichagua. Reñemoĩ tembiapo, ha peteĩteĩ tembiapo oguereko peteĩ líder ha peteĩ atyha michĩ. Reñe'ẽ pe líder ndive, Discord-icha, ha emombe'u chupe peteĩ ñemoñe'ẽ; pe líder ombojoapy kuatia ha plan-pe, upéi oha'arõ reipytyvõ Go. Pe atyha omba'apo kuatia rupi tape rupi, peteĩ comando línea tembiguáipe ojejapóva ñe'ẽ modelo-pe guarã. Oĩ mboyve ñemoĩ ndéve, peteĩ AI tester oho tapykuépe peteĩ kopia aplicación-pe ha omoĩ hese peteĩ pantalla ta'angapy. Tembiapo opáva oguahẽ nde ñemoĩ-pe umi marandu ojoko'ívape ha pe diff ndive. Eaceptar, térã ehejá peteĩ ñe'ẽ ha pe atyha oñemoĩ jey ha oha'ã jey hikuái. Nde añoite ikatu emongu'e peteĩ kuatia Ojejapopáma-pe, avave ndaikatúi.","Peteĩ ára AI-gile ndive, sa'i ha sa'i. Ka'aru reheja sa'i ñe'ẽ: ko votõ ndaha'éi hendápe, ko lista oñemoĩ vaerã hekopete, ikatu piko jaguereko modo pytũ. Upéi reho reke. Umi agente omoñe'ẽ umi ñe'ẽ, ojapo umi ñemoambue, oprueba ha ombohasa jey ndéve. Ojejapótava opa ramo, pyhare ñangareko ombyaty ko'ã kuatia backlog-gui, ndoikotevẽiva nde mbohovái. Ko'ẽrõ oĩ peteĩ ñemoĩ mbyky ha michĩ: mokõi porandu ha sa'i mba'e eprueba haguã, peteĩteĩ tape ndive ikatúva omuña peteĩ tapicha ke'ỹ, ha peteĩ pantalla ta'angapy omba'apóva. Eikutu, eaceptar umi porãva ha emondo jey ambue. Peteĩ token jepapa ohechauka mboy ojeporu, ha No Token Mode oĩ ára michĩvape guarã. Upéi reñembojuka, ha umi agente ndaikatúi gueteri oipytyvõ upépe. Péicha opa ára oñepyrũ ha opa porã, ha nde reikuaa mba'e ojejapo.","Raẽ, mba'e AI-gile ndaha'éiva. Ndaha'éi startup, ndojehepyme'ẽi, ha avave ndombyaty nde dato. Ha'e peteĩ tabla mba'e'ỹre omba'apóva nde mba'e'oka-pe, ndaipóri cuenta, ndaipóri tracker ha ndaipóri cookie. Ha'e: peteĩ tenda hekopete ehecha haguã opa tembiapo código AI peteĩ jey, peteĩ atyha agente ojapóva umi kuatia ha nde ejapóva umi jeporavo. Ombyaty kuatia joapýva peteĩme, omoĩporã téra ñembyaíva, ha ohecha pe código opyta hesakã ha michĩ. Oñe'ẽ 120 ñe'ẽ rupi, holandés ha flamenco guive pirata ha klingon peve. Angirũ kuéra ikatu oñemondo marandu, ñemigua ha oñemigua pyteguápe. Rich ojapo hetaiterei agente ipasiénsiavape ndive, ojeporúva hekovépe ohóvo. Oĩ pre-alfa mboty-pe, upévare oĩ ipiru'ã ha'ekuéra. Ndéve ombovy'a ramo, eporandu porãme ha ikatu reike raẽ, ha ipyahu. Ñande ñemoirũ ha ñañemoĩ potĩ ñane rembiapo, sa'i sa'i, ha opa ára ñamba'apo."]}],"quips":{"1":"Peteĩ ñe'ẽ. Py'aguasu. Ikatu hetaiterei.","3":"Mbohapy ñe'ẽ. Ojeroviaha hetave heta producto páhina-gui.","8":"Mokõi ñe'ẽ ha irundy. Gueteri mbykyve peteĩ kafe-ñepyrũ-gui.","21":"Pukukue ha'e story point, upéicha. Ikatuha ndaha'éiramo.","55":"Cincuenta y cinco ñe'ẽ. Mokõi kuatia opa ereñe'ẽ aja ko'ã.","144":"Péva ha'e puku. Ndaipóri 233. Umi agente oho oke."}},"timeline":{"first-idea.name":"Ñemoñe'ẽ ñepyrũ","first-idea.line":"Ñe'ẽ ñepyrũ, ndaipóri mboyve código.","first-board.name":"Tabla ñepyrũ","first-board.line":"Peteĩ tabla ohecha hembiapo: kuatia, columna, jegueru ha mombyry, tembiapo.","team-roles.name":"Atyha ha tembiapo","team-roles.line":"Agente perfil, atyha plantilla, tenda ha máva ojapo mba'e.","install.name":"Ñemoĩ ha versión","install.line":"Peteĩ zip angirũ ikatúva omoĩ, ijehegui oñembopyahu, canal ha jeho jey.","usage-saver.name":"Jeporu ñeñongatu","usage-saver.line":"Emedí mboy hepy ojejapo, eñongatu código hesakã, eñongatu nde límite.","friends.name":"Angirũ ha ñemoherakuã","friends.line":"DM ñemigua, relé ñemigua, ñehenói, tembiapo ha tembiapo oñemoherakuãva.","languages.name":"Ñe'ẽ","languages.line":"Opa pantalla ñe'ẽ peteĩ ñe'ẽ marandu-pe, holandés ha flamenco raẽ.","ai-tester.name":"AI tester","ai-tester.line":"Peteĩ tester ohecha opa ñemoĩ raẽ ha ohechauka mba'e ohecha.","website.name":"Pe sitio web","website.line":"aigile.lol, pe teaser ha ko ára tape.","streaming.name":"Chat ha streaming","streaming.line":"Discord, Twitch, OBS, streamer modo, GIF ha emoji.","no-ai.name":"Edición AI'ỹre","no-ai.line":"Peteĩ tabla tapicha ojapóvape código AI'ỹre, ha tabla públicas.","night-watch.name":"Pyhare ñangareko","night-watch.line":"Peteĩ ñangarekohára ha Scrum Master omoĩ atyha tembiapo-pe reiko aja ereke.","p-more.name":"Opa ambue","p-more.line":"Ñemoñe'ẽ michĩvéva oha'arõva hendápe.","p-android.name":"Teléfono ha Android","p-android.line":"Eguahẽ nde tabla-pe teléfono-gui, upéi Android aplicación hekoite.","p-release.name":"Alfa ha upéi","p-release.line":"Alfa mboty, sitio oikovéva, upéi beta.","p-languages.name":"Hetave ñe'ẽ","p-languages.line":"130 ñe'ẽ, ha peteĩ modo inmersión oñemoarandúvape g̃uarã.","p-engines.name":"Hetave AI motor","p-engines.line":"Eiporavo Claude, Codex, Gemini, Copilot térã Cursor peteĩ teĩ agente-pe g̃uarã.","p-pro.name":"Profesional jepuru","p-pro.line":"Riesgo etiqueta, merge okẽ, incidente kuatia ha guardarraíl.","p-self.name":"Ñeñangareko ndejehe","p-self.line":"Kane'õ modo, ñeñangareko ñemomandu'a ha 4:20.","p-servers.name":"Servidor ha tuichakue","p-servers.line":"Servidor ñemoĩ opaite, tembiapo ha plan okakuaa haguã.","p-livestream.name":"Streaming ambue","p-livestream.line":"Twitch chat, emoji ijehegui ha jehecha pyahu público."},"words":{"button":"📖 Tembiapo ñe'ẽ","h":"📖 Ñe'ẽ ojehechaukáva","intro":"Ñembokatupyry sãso ñe'ẽ ndahasýivape: opa ñe'ẽ rejuhúva peteĩ idea ypykue guive peteĩ servicio tapichakuéra ojeroviáva hese peve, Agile, ñemopu'ã, seguridad ha AI ndive ñemba'apo reheve tape pukukue javeve.","search":"Eheka peteĩ ñe'ẽ…","none":"Ndaipóri ñe'ẽ ojojáva.","close":"Emboty","count":{"one":"{count} ñe'ẽ","other":"{count} ñe'ẽ"},"groups":[{"id":"idea","name":"💡 Mba'e ñemoñepyrũ ha jeheka"},{"id":"plan","name":"🗺️ Tembiapo ñeplanea"},{"id":"agile","name":"🔁 Agile tembiapo rape"},{"id":"build","name":"🛠️ Ñemopu'ã"},{"id":"test","name":"🧪 Ñeha'ã ha calidad"},{"id":"change","name":"🔀 Ñemoambue hekopete"},{"id":"run","name":"🛎️ Peteĩ servicio ñangareko"},{"id":"sec","name":"🔒 Seguridad ha privacidad"},{"id":"ai","name":"🤖 AI ndive ñembaapo"},{"id":"money","name":"💰 Pirapire ha licencia"}],"list":[{"id":"discovery","g":"idea","word":"Jeheka (Discovery)","text":"Pe ñepyrũrã, rehecha haguã mba'e problema ovale ñemyatyrõ ha mávape g̃uarã, oñemopu'ã mboyve mba'eve.","also":["jeheka ñepyrũ","discovery"]},{"id":"problemstmt","g":"idea","word":"Jehasa'asy ñemombe'u","text":"Peteĩ térã mokõi ñe'ẽjoaju he'íva máva oguereko peteĩ problema, mba'épa ha mba'ére iñimportante, opavave oho haguã peteĩ gotyo.","also":["jehasa'asy ñemombe'ukuéra"]},{"id":"user","g":"idea","word":"Oiporúva","text":"Peteĩ tapicha oiporúva umi mba'e rejapóva. Pe tembiapo ojejapo hemikotevẽ rehe.","also":["oiporúvakuéra"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder (interesado)","text":"Oimeraẽ tapicha oñeñangarekóva mba'éichapa osẽta pe tembiapo térã ohupytýva chupe, techapyrã umi ohepyme'ẽva, oiporúva térã oipytyvõva.","also":["stakeholders","interesado","interesadokuéra"]},{"id":"persona","g":"idea","word":"Persona","text":"Peteĩ tapicha ojeinventáva ha katu ojoguáva añeteguápe, ohechaukáva peteĩ oiporúva ñemoha'ãnga, ikatu haguã atyha oporandu “ndahasýipa ko'ã Sam-pe g̃uarã?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"Oiporúva ñehesa'ỹijo","text":"Ñemongeta ha jehecha tapicha añetegua ndive, reikuaa haguã mba'épa oikotevẽ, ndaha'éi ja'adivina.","also":["oiporúva ñemongeta"]},{"id":"journey","g":"idea","word":"Oiporúva rape","text":"Umi paso peteĩ tapicha ojapóva ohupyty haguã peteĩ mba'e, ohendu ypy guive opa peve, avei nde producto okápe. Rehaíramo, ojehecha moõpa ojejoko.","also":["oiporúva rapekuéra","customer journey","user journey"]},{"id":"painpoint","g":"idea","word":"Mba'e hasýva","text":"Peteĩ mba'e ombopochy térã ombotardéva tapichakuérape ko'ag̃aite. Producto porã oipe'a umi mba'e hasýva.","also":["mba'e hasýva","pain point"]},{"id":"assumption","g":"idea","word":"Ojeroviáva (assumption)","text":"Peteĩ mba'e rejeroviáva ha katu ndereñeha'ãi gueteri hese. Rehaíramo umíva, ojehecha mba'e reñeha'ãva'erã raẽ.","also":["ojeroviáva","assumptions","suposición"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"Pe ñemoha'ãnga iporãvéva reñeha'ãtava, mba'épa reha'arõ oiko reheve, techapyrã “tapichakuéra oñeinscribíta pe peteĩha jasy sãsõramo”.","also":["hypotheses","hipótesis"]},{"id":"experiment","g":"idea","word":"Ñeha'ã (experiment)","text":"Peteĩ prueba michĩ oñeplaneáva, reikuaa haguã peteĩ idea ombaapópa, reapostá mboyve heta hese.","also":["ñeha'ãkuéra","experiment"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"Peteĩ ñeha'ã pya'e ha sencillo, rehecha haguã ikatúpa oiko peteĩ idea. Jepi oñemombo rehupyty rire pe ñembohovái.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"Peteĩ modelo ypykue producto rehegua, jepi ra'ãnga ikatúva reikutu, reñeha'ã haguã pe idea tapicha ndive remopu'ã porã mboyve.","also":["prototypes","prototipo"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"Peteĩ dibujo sencillo peteĩ pantalla rehegua, ohechaukáva moõpa oĩta mba'e, sa'y ha contenido añetegua'ỹre.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"Peteĩ ra'ãnga hesakãporãva mba'éichapa ojehecháta peteĩ pantalla, sa'y ha moñe'ẽrã añetegua reheve, ha katu mba'eve ndoikói gueteri.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"Mba'érepa ojejapo peteĩ tembiapo: mboy hepy, mba'e ogueru térã oñongatu, ha umi riesgo.","also":["business cases","caso de negocio"]},{"id":"feasibility","g":"idea","word":"Ikatu jejapo (Feasibility)","text":"Ikatúpa añetehápe ojejapo ha oñeñangareko peteĩ mba'ére pe aravo, pirapire ha katupyry reguerekóva reheve.","also":["ikatúva"]},{"id":"outcome","g":"idea","word":"Resultado (outcome)","text":"Pe ñemoambue reipotáva tapichakuérape g̃uarã, techapyrã sa'ive tapicha ohejáva hi'turno. Upéva iñimportanteve mboýpa rejapo.","also":["resultado","outcome","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Ojejapóva (output)","text":"Peteĩ mba'e atyha ojapóva, techapyrã peteĩ pantalla pyahu térã peteĩ informe. Ojejapo haguére, ndaha'éi oipytyvõmaha voi oimeraẽvape.","also":["ojejapovakuéra","output","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Papapy jehupyty (success metric)","text":"Peteĩ papapy he'íva ndéve pe tembiapo ojapópa ojejapo haguã, techapyrã hetave tapicha omohu'ã ipedido.","also":["papapy jehupyty","success metric","success metrics","métrica de éxito"]},{"id":"kpi","g":"idea","word":"Papapy iñimportantevéva (KPI)","text":"Peteĩ papapy iñimportánteva rehecháva reikuaa haguã oho porãpa, techapyrã mboy tapicha oñeinscribi arapokõindy ñavõ.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objetivo ha resultado clave (OKR)","text":"Peteĩ tape remoĩ haguã jehupytyrã: pe objetivo he'i mba'e reipota, ha mbovymi resultado clave ha'e umi papapy ohechaukáva rehupytymaha.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Producto","text":"Pe mba'e ojejapóva ha oñeñangarekóva umi oiporúva g̃uarã, techapyrã peteĩ app, peteĩ web térã peteĩ tembiporu.","also":["productokuéra","products"],"noTip":1},{"id":"vision","g":"plan","word":"Producto visión","text":"Peteĩ ñe'ẽ mbyky he'íva mávape oipytyvõ pe producto ha mamo gotyo oho are rire.","also":["vision","vision statement","visión"]},{"id":"po","g":"plan","word":"Producto jára (PO)","text":"Pe tapicha odesidíva mba'e ojejapóta ha mba'e orden-pe, atyha ombaapo haguã tapiaite pe iñimportantevévare. AI-gile-pe upéva ha'e nde.","also":["PO","product owner","product owners"]},{"id":"pm","g":"plan","word":"Producto ñangarekohára (PM)","text":"Pe tapicha oñangarekóva mamo gotyo oho peteĩ producto: mba'e problema omyatyrõ, mávape g̃uarã ha mba'ére. PM he'ise avei project manager, upévare eporandu mávapa he'ise.","also":["producto ñangarekohárakuéra","product manager"]},{"id":"projmgr","g":"plan","word":"Tembiapo ñangarekohára","text":"Pe tapicha oñangarekóva peteĩ tembiapo opa haguã itiempo-pe ha presupuesto ryepýpe, ohechávo máva ojapo mba'e ha araka'e peve.","also":["tembiapo ñangarekohárakuéra","project manager"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"Peteĩ plan sencillo mba'épa oúta umi jasy oúvape, orden-pe. Ohechauka mamo gotyo, ndaha'éi fecha exacta, ha oñemoambue reikuaave vove.","also":["roadmaps","hoja de ruta"]},{"id":"milestone","g":"plan","word":"Hito (milestone)","text":"Peteĩ momento pe tembiapópe ovaléva ojehechauka, techapyrã “peteĩha versión oĩma línea-pe” térã “100 oiporúva”.","also":["hito","hitokuéra","milestone","milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"Pe producto versión michĩvéva oipytyvõ gueteri tapicha añeteguápe, ikatu haguã reaprende chuguikuéra pya'e.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Ñeikotevẽ","text":"Peteĩ mba'e pe producto opámava ojapova'erã térã ha'eva'erã.","also":["ñeikotevẽkuéra","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Alcance (scope)","text":"Mba'épa oike pe tembiapópe ha, iñimportante peteĩcha, mba'épa ndoikéi.","also":["alcance","in scope","out of scope","oĩ alcance-pe","ndoĩri alcance-pe"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"Oñembojoapy jave tembiapópe hetave ha hetave mbeguemi, avave oñemoneĩ'ỹre pe aravo térã gasto extra rehe, upévare ndopaitéi araka'eve.","also":["feature creep","alcance okakuaáva"]},{"id":"feature","g":"plan","word":"Feature","text":"Peteĩ mba'e pe producto ojapokuaáva tapichakuérape g̃uarã, techapyrã “emoĩ jey nde ñe'ẽ ñemi”.","also":["features","funcionalidad"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"Peteĩ tembiapo tuicháva, tuichaiterei ojejapo haguã peteĩ jeýpe, upévare oñemboja'o kuatia michĩvévape.","also":["epics"]},{"id":"story","g":"plan","word":"User story (oiporúva rembiasa)","text":"Peteĩ tembiapo michĩ ojehaíva oiporúva rendágui: “Che, ajoguáva ramo, aipota añongatu che carrito, ikatu haguã amohu'ã upéi.” Omoñepyrũ peteĩ ñemongeta mba'épa ojejapóta rehe.","also":["user story","user stories","oiporúva rembiasa"]},{"id":"ac","g":"plan","word":"Criterio de aceptación (AC)","text":"Umi prueba peteĩ kuatia ohasava'erã ojeipapa haguã opámava ramo, oñemoneĩva tembiapo oñepyrũ mboyve, techapyrã “che carrito oĩ gueteri asẽ rire ha aike jey rire”.","also":["acceptance criteria","AC","criterio de aceptación"]},{"id":"task","g":"plan","word":"Tembiapo michĩ (task)","text":"Peteĩ tembiapo año ojejapova'erã, jepi peteĩ paso michĩ peteĩ user story tuichavévagui.","also":["tembiapo michĩ","tasks","task"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Ambue téra kuatia rehegua: peteĩ tembiapo térã peteĩ jerure, ojehecháva ñepyrũ guive opa peve.","also":["tickets"]},{"id":"priority","g":"plan","word":"Tenondegua (prioridad)","text":"Mba'eichaitépa iñimportante térã ipya'eva'erã peteĩ mba'e ambue mba'e ndive, pe iñimportantevéva oho haguã raẽ.","also":["tenondeguakuéra","priority","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Ñemoĩ prioridad","text":"Ñemoĩ tembiapo orden-pe iñimportanteháicha. Peteĩ tape ojeporúva hína MoSCoW: Must have (oĩva'erã), Should have (oĩ porãva'erã), Could have (ikatu oĩ), Won’t have (ndoikemo'ãi ko'ág̃a).","also":["MoSCoW","priorización"]},{"id":"estimate","g":"plan","word":"Ñemoha'ãnga (estimate)","text":"Pe ñemoha'ãnga iporãvéva mba'eichaitépa tuicha térã mboy aravo oipe'a peteĩ tembiapo. Ñemoha'ãnga, ndaha'éi ñe'ẽme'ẽ.","also":["estimate","estimates","estimation","estimación"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"Peteĩ tape ojeporúva ojeipapa haguã tembiapo tuichakue, kuatiakuéra ojoguerahávo ojuehe (“mokõi jey tuichave pe ambuégui”), ndaha'éi aravo rupi. Ndojeporúi ojejoguerahávo atyhakuéra.","also":["story point","story pointkuéra"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Ojeipapa tembiapo tuichakue S, M, L térã XL ramo. Pya'e ha oĩ porã ñepyrũrã plan g̃uarã.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Peteĩ ñembosarái ojeipapa haguã: opavave ohechauka peteĩ kuatia tuichakue reheve peteĩ jeýpe, upéi pe ohechaukáva tuichavéva ha michĩvéva he'i mba'érepa.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependencia (dependency)","text":"Peteĩ tembiapo ndaikatúi oñepyrũ térã opa, ambue opa peve.","also":["dependencia","dependency","dependencies"]},{"id":"blocker","g":"plan","word":"Ojejokóva (blocker)","text":"Oimeraẽ mba'e ojokóva tembiapo ani haguã oho tenonde ko'ag̃aite, techapyrã peteĩ ñembohovái ndoúiva gueteri térã peteĩ tembiporu oñembyaíva.","also":["blockers","ojejokóva"]},{"id":"deadline","g":"plan","word":"Ára paha (deadline)","text":"Pe ára peve peteĩ mba'e oñemohu'ãva'erã.","also":["deadline","deadlines","fecha límite"],"noTip":1},{"id":"deliverable","g":"plan","word":"Entregable (deliverable)","text":"Peteĩ mba'e ojehecha ha ojepokokuaáva pe tembiapo ojapo ha oñeme'ẽva, techapyrã peteĩ página ombaapóva térã peteĩ informe.","also":["entregable","deliverable","deliverables"]},{"id":"forecast","g":"plan","word":"Pronóstico (forecast)","text":"Ñemoha'ãnga mba'épa ikatuvéta oiko, techapyrã araka'e opáta pe tembiapo, ko'ag̃aite peve reikuaáva rehe.","also":["pronóstico","forecast","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Métrica (metric)","text":"Oimeraẽ mba'e rehecháva mboýpa ha resegíva ára ohasávo, techapyrã mboy jey ojeike peteĩ páginape térã mboy aravo oipe'a peteĩ arreglo.","also":["métrica","metric","metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"Umi mba'e tapichakuéra he'íva ndéve nde rembiapo rehe, iporãva ha ivaíva. Rehupyty pya'e ha jepi, upéva ha'e Agile korasõ.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Pe lista oha'arõva idea ha tembiapo noñeplaneáiva gueteri, iñimportantevéva yvate gotyo. Mba'eve upépe ndojejapói ohasa peve Ojejapótava-pe."},{"id":"sprint","g":"agile","word":"Sprint","text":"Peteĩ tembiapo aravo mbyky ha ojeikuaáva (jepi peteĩ térã mokõi arapokõindy, araka'eve peteĩ jasygui hetave), peteĩ jehupytyrã ha kuatia oñemoneĩva reheve ojejapopa haguã.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Peteĩ ñembyaty pya'e ára ñavõ: mba'épa ojapo peteĩteĩ atyha guápe, mba'épa ojapóta upéi, ha mba'épa ojoko chupe. Scrum-pe oñehenói daily scrum.","also":["standup","stand-ups","daily scrum","daily stand-up"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Peteĩ tape ombaapo haguã, kuatiakuéra ohasahápe tabla kolumna rupi (techapyrã Ojejapótava, Ojejapóva, Ojejapopáma) ha atyha omoĩ límite mboy tembiapo oĩ ojejapo aja peteĩ jeýpe, tembiapo osegi haguã oho."},{"id":"wip","g":"agile","word":"WIP limit","text":"WIP he'ise work in progress (tembiapo ojejapo aja). Peteĩ WIP limit ha'e mboy kuatia hetavéva peteĩ kolumna oguerekova'erã peteĩ jeýpe, atyha omohu'ã haguã mba'e oñepyrũ mboyve ambue.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"Atyha lista mbykymi he'íva mba'épa he'ise “opáma”, oñeha'ãma ha ojehechaukámaicha, peteĩ kuatia ojegueraha mboyve ndéve. Ijykéregua, Definition of Ready, he'i araka'épa peteĩ kuatia hesakã porã oñepyrũ haguã.","also":["Definition of Ready","DoD","DoR"]},{"id":"retro","g":"agile","word":"Retro","text":"Peteĩ ma'ẽ tapykuépe jepiguáva mba'éichapa atyha ombaapo, oñemoneĩ haguã peteĩ térã mokõi mba'e ojejapo porãve haguã upéi. Retrospective ñe'ẽ mbykýpe. AI-gile-pe peteĩ retro he'i peteĩ ñemoambue atyha rembiapo reko rehe, ha nde ere Go térã Ndaiporãi gueteri.","also":["retros","retrospectiva"]},{"id":"swarm","g":"agile","word":"Swarm","text":"Opavave po tembiapópe: heta tapicha oheja ambue tembiapo omyatyrõ haguã oñondive peteĩ mba'e urgente oñemohenda peve. AI-gile-pe opa atyha oipytyvõ peteĩ tembiapópe, ha umi ambue tembiapo oha'arõ upe aja.","also":["swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Scrum-pe, pe tapicha oipytyvõva atyha ombaapo porã haguã: oipe'a umi mba'e ojokóva, oñangareko ñembyaty oho porã haguã ha ombo'e teko porã, avavépe omanda'ỹre. AI-gile-pe Lead Scrum Master ohecha kuatia ojejokóva, omomýi atyhakuérape ha omomandu'a ndéve mba'épa oha'arõ, opa tembiapópe.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Peteĩ tape ombaapo haguã paso michĩ rupi: ejapo michĩmi, ehechauka jepi resultado añetegua, eaprende tapichakuéra he'ívagui ha emoambue pe plan reho rehohápe, ani replanea opa mba'e ñepyrũrãme.","also":["Agile development","agile ways of working","Agile"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"Peteĩ ñe'ẽ mbyky ohaíva 2001-pe software apohára. Omoĩ tenondete tapichakuéra, resultado ombaapóva, tembiapo cliente ndive ha jehovái ñemoambuépe, plan pohýi ha kuatia hetaitérevagui.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"Tembiapo rape ymaguare: eplanea opa mba'e, upéi ejapo opa, upéi eñeha'ã opa, peteĩ etapa ambue rire. Ñemoambue ipahápe hasy ha hepy.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"Peteĩ vuelta ojejapo, ojehecha ha oñemyatyrõ peteĩ mba'e. Agile tembiapo ha'e heta vuelta peichagua, ha sprint ha'e peteĩ chuguikuéra.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"Peteĩ pehẽngue pyahu ombaapóva oñembojoapýva producto-pe peteĩ sprint térã vuelta pukukuépe, ha ojoaju porã umi oĩmavavoi ndive.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Peteĩ Agile tape ojeporuvéva: peteĩ atyha michĩ ombaapo sprint mbykýpe peteĩ jehupytyrã gotyo, rol hesakãva ha mbovymi ñembyaty jepiguáva reheve oplanea, ohecha ha omyatyrõ haguã."},{"id":"scrumteam","g":"agile","word":"Scrum atyha","text":"Pe aty michĩ ojapóva tembiapo Scrum-pe: producto jára, Scrum Master ha programadorkuéra.","also":["Scrum atyhakuéra","Scrum team"]},{"id":"ceremonies","g":"agile","word":"Scrum ñembyaty","text":"Umi ñembyaty jepiguáva Scrum-pe: sprint planning, daily scrum, sprint review ha retro. Heta tapicha ohenói chupekuéra ceremonias.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint ñeplanea","text":"Pe ñembyaty sprint ñepyrũme, atyha oñemoneĩhápe mba'ére iñimportante pe sprint, mba'e kuatia ogueraháta ha mba'éichapa oñepyrũta.","also":["planning meeting","sprint planning"]},{"id":"sprintgoal","g":"agile","word":"Sprint jehupytyrã","text":"Peteĩ ñe'ẽjoaju he'íva mba'ére g̃uarã pe sprint. Umi tarea michĩ ikatu oñemoambue tapére, ojehupyty guive pe jehupytyrã.","also":["sprint goals","sprint goal","objetivo del sprint"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"Umi kuatia oñeiporavóva ko sprint-pe g̃uarã, atyha plan reheve ojapo haguã chupekuéra.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Producto backlog","text":"Pe lista entero orden-pe opa mba'e ikatúva ojejapo producto-pe g̃uarã, iñimportantevéva yvate gotyo. Oñemoambue tapiaite reaprende vove.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Producto jehupytyrã","text":"Pe resultado tuichavéva pe producto ohupytyséva, ha oipytyvõva atyhápe oiporavo haguã mba'épa ojapóta upéi.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement (ñemyatyrõ)","text":"Jepi ojehasa pe backlog rupi, oñemopotĩ, oñemboja'o, oñemoĩ orden-pe ha oñembojoapy detalle kuatiakuérape, oĩmbá haguã ojegueraha haguã. Oñehenói avei backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint jehecha","text":"Peteĩ ñembyaty sprint opávo, atyha ohechaukahápe mba'épa omohu'ã ha ohendu mba'épa opensa tapichakuéra, odesidi haguã mba'épa oúta upéi.","also":["sprint reviews","sprint review"]},{"id":"demo","g":"agile","word":"Demo","text":"Ehechauka tembiapo opámava ombaapohápe, en vivo, umi ojeruréva chupe.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"Peteĩ aravo ojeikuaáva peteĩ mba'e g̃uarã. Opa vove, repyta, naiñopambáiramo jepe opa mba'e.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"Mboy tembiapo peteĩ atyha jepi omohu'ã peteĩ sprint-pe, ojeporúva oplanea haguã mboy ogueraháta upéi. Ndaha'éi puntaje mba'eichaitépa tapichakuéra ombaapo mbarete.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"Mboy tembiapo atyha ikatu ogueraha peteĩ aravo pukukuépe, ojeipe'a rire vacaciones ha ambue tembiapo.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"Peteĩ gráfico tembiapo hembýva sprint-pe, oguejýva ára ha ára. Pe línea opytáramo plano, oĩ mba'e ojejokóva.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"Peteĩ gráfico tembiapo opámava ojupíva ára ohasávo, oñeplaneáva entero ykére, ikatu haguã rehecha araka'épa reguahẽta.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban tabla","text":"Pe tabla voi: peteĩ kolumna tembiapo etapa ñavõ, ha kuatiakuéra ohasa hese rupi.","also":["Kanban boards","Kanban tablakuéra"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"Peteĩ tape ombaapo haguã, tembiapo pyahu oñepyrũhápe oĩ jave añoite peteĩva ikatúva ogueraha, ndaha'éi ojemoinge ñembojaru ijyvagui henyhẽmava.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"Mba'eichaitépa oho porã tembiapo tabla rupi. Flow porã he'ise kuatiakuéra oho tapiaite, ha ndojeamontonái.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"Mboy aravo ohasa peteĩva ojerure guive peteĩ mba'e, opa peve.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"Mboy aravo ohasa peteĩ kuatia oñepyrũ guive añetehápe hese tembiapo, opa peve.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"Mboy kuatia opa peteĩ arapokõindýpe, térã oimeraẽ aravo ojeikuaávape.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"Pe etapa tembiapo ojeamontonahápe ha ombotardéva opa mba'e hapykuépe, botella ajúra po'iháicha.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"Peteĩ fila tabla rupi ombyatýva kuatia peteĩ mba'eguáva, techapyrã tembiapo urgente térã peteĩ atyha kuatiakuéra.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Peteĩ tape ombaapo haguã oipe'áva pe mba'e rei (oimeraẽ mba'e ndoipytyvõiva cliente-pe) ha oheja tembiapo oho tapiaite."},{"id":"waste","g":"agile","word":"Waste","text":"Lean-pe, oimeraẽ mba'e oipe'áva kyre'ỹ ha ndoipytyvõiva cliente-pe, techapyrã ha'arõ, ejapo jey térã ojejapo mba'e avave oiporu'ỹva.","noTip":1},{"id":"kaizen","g":"agile","word":"Mejora continua (kaizen)","text":"Ñañemyatyrõve mbeguemi tapiaite ñemoambue michĩ jepiguáva rupi, ha upéi ojehecha oipytyvõpa. Retro ha'e peteĩ tape ojejapo haguã. Oñehenói avei kaizen.","also":["kaizen","continuous improvement","mejora continua"]},{"id":"selforg","g":"agile","word":"Atyha ijehegui oñemohendáva","text":"Peteĩ atyha odesidíva ijehegui mba'éichapa ojapóta pe tembiapo, ha ndaha'éi oñeme'ẽva chupe orden paso ha paso.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional atyha","text":"Peteĩ atyha oguerekóva opa katupyry oikotevẽva omohu'ã haguã ijehegui pe tembiapo, techapyrã diseño, ñemopu'ã ha ñeha'ã.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"Peteĩ jeheka mbyky, aravo ojeikuaáva reheve, ombohovái haguã peteĩ porandu reñepyrũ mboyve pe tembiapo añeteguápe.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Ojejapo jey peteĩ tembiapo, ndoiko porãi haguére peteĩha jeýpe.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Tape ojeporu haguã Agile heta atyha ndive peteĩ organización tuichápe. SAFe (Scaled Agile Framework) ha'e peteĩ techapyrã ojekuaaporãva.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Pe tembiapo folder código rehegua, commit rembiasakue entero reheve. Ikatu oĩ nde mba'e'oka-pe, GitHub-pe, térã mokõivévape.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Peteĩ rape tembiapo código-pe, ikatu haguã ojejapo ñemoambue ndojepokói hague pe versión tuicha.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Peteĩ ra'ãnga oñeñongatúva código-gui, marandu mbyky rehe mba'e oñemoambue. Ikatu reñemboguevi tapiaite peteĩme.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Remondo umi ra'ãnga reñongatuva'ekue (commit) ko mba'e'okágui pe copia ojepurúvape oñondive internet-pe, techapyrã GitHub, ikatu haguã opyta seguro ha ambue ohupyty."},{"id":"merge","g":"build","word":"Merge","text":"Oñembojoaju umi ñemoambue peteĩ branch-gui ambuépe, jepi ojevy jave main versión-pe."},{"id":"pr","g":"build","word":"Pull request","text":"Ojejerure ojehecha ha oñembojoaju haguã peteĩ branch ñemoambue main versión-pe. Oĩ web ohenóiva merge request.","also":["PR","PRs","merge request"]},{"id":"refactor","g":"build","word":"Refactor","text":"Emopotĩ código ndoguerohoryiva mba'e ojapo: marandu'i michĩve, réra hesakãvéva, sa'ive jehu jey."},{"id":"bug","g":"build","word":"Bug","text":"Mba'e ndoguatái oñeha'arõháicha.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Peer review","text":"Ambue mokõi tesa: peteĩ ndaha'éiva ohaiva'ekue ohecha pe tembiapo og̃uahẽ mboyve nde rendápe, ohasa haguã sa'ive jejavy. AI-gile-pe ambue AI ohecha peteĩteĩ kuatia.","also":["code review","jehechajey"]},{"id":"code","g":"build","word":"Código","text":"Umi instrucción ojehaíva he'íva peteĩ mba'e'oka-pe mba'épa ojapova'erã. Oñehenói avei código fuente (source code).","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Lenguaje de programación","text":"Peteĩ ñe'ẽ ojehai haguã código, techapyrã JavaScript, Python térã Java. Peteĩteĩ oĩ porãve peteĩ tembiapo g̃uarã.","also":["lenguaje de programación","programming languages","programación ñe'ẽ"]},{"id":"developer","g":"build","word":"Programador (dev)","text":"Peteĩ tapicha ohaíva ha omoambuéva código. Oñehenói avei programador térã software engineer.","also":["developer","developers","programmer","programmers","software engineer","programador","desarrollador"]},{"id":"software","g":"build","word":"Software","text":"Umi programa oñembaapóva mba'e'oka ha celular-pe, ndaha'éi umi máquina voi (pe hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Application ñe'ẽ mbykýpe: peteĩ programa tapichakuéra oiporúva ojapo haguã peteĩ mba'e, celular-pe, mba'e'oka-pe térã navegador web-pe.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"Peteĩ app oñembaapóva navegador web-pe, upévare ndaipóri mba'eve reinstala haguã.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"Pe app pehẽngue rehecháva ha reikutúva: pantalla, botón ha ñe'ẽ, jepi nde navegador-pe.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"Pe app pehẽngue ojehecha'ỹva, oñongatúva dato ha ojapóva tembiapo reikutu vove peteĩ mba'e, techapyrã ohecha nde ñe'ẽ ñemi oĩ porãpa.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Ombaapo front end ha back end-pe mokõivévape.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"Mba'e peteĩ tapicha ohecha ha oiporúva pantalla-pe: mba'e oĩháicha, botón, menú ha moñe'ẽrã.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"Mba'éichapa reñeñandu reiporúvo peteĩ mba'e: ndahasýi, hesakã ha nderevy'a, térã ndeakãnga'u ha ipererĩ.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accesibilidad (a11y)","text":"Ojejapo mba'e opavave ikatu haguã oiporu, avei umi ndohecha porãiva, ndaikatúiva oiporu mouse térã oiporúva lector de pantalla.","also":["a11y","accessibility","accesibilidad"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Ojejapo página ohenda ha ombaapo porã haguã oimeraẽ pantalla tuichakuépe, celular guive monitor tuicha peve."},{"id":"designsys","g":"build","word":"Design system","text":"Peteĩ kit ojepuru oñondive sa'y, letra, botón ha regla reheve, opa pantalla ojehecha ha oiko haguã peteĩcha.","also":["design systems"]},{"id":"architecture","g":"build","word":"Arquitectura","text":"Peteĩ sistema ra'ãnga tuichakue: mba'épa umi pehẽngue tenondegua ha mba'éichapa oñomongeta ojupe."},{"id":"database","g":"build","word":"Base de datos (DB)","text":"Peteĩ henda oñeñongatuhápe marandu orden-pe, peteĩ planilla ipu'akaitéva ojoguáva, pe app ikatúva omoñe'ẽ ha omoambue.","also":["database","databases","DB","bases de datos"]},{"id":"schema","g":"build","word":"Database schema","text":"Peteĩ base de datos mba'éichapa oñemohenda: mba'e tabla marandu rehegua oguereko ha mba'épa oike peteĩteĩme.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Structured query language ñe'ẽ mbykýpe: pe ñe'ẽ ojeporúva ojejerure haguã marandu heta base de datos-pe térã ojeambue haguã.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Dato","text":"Marandu peteĩ mba'e'oka oñongatúva, techapyrã téra, pedido térã ñemboheko.","also":["dataset","datasets","datokuéra"],"noTip":1},{"id":"server","g":"build","word":"Servidor","text":"Peteĩ mba'e'oka hendýva tapiaite ha ombohováiva ambue mba'e'oka jerure, techapyrã omondo peteĩ página web reike vove hese.","also":["servers","servidorkuéra","server"]},{"id":"client","g":"build","word":"Cliente","text":"Pe lado ojeruréva peteĩ mba'e, jepi nde navegador térã app, oñomongetáva peteĩ servidor ndive. Negocio-pe he'ise avei peteĩ cliente ojoguáva.","also":["clients","clientekuéra","client"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Application programming interface ñe'ẽ mbykýpe: peteĩ menú jerure rehegua, peteĩ programa ikatúva ojapo ambuépe, techapyrã ojerure peteĩ servicio clima-pe pronóstico ko árape g̃uarã.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"Peteĩ mba'e API menú-pe: peteĩ dirección web peteĩ programa ikatúva ohenói ohupyty térã omondo haguã peteĩ mba'e.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integración","text":"Ojejoaju mokõi sistema ombaapo haguã oñondive, techapyrã nde tenda omondo pedido nde software contabilidad-pe.","also":["integrations","integration","integraciones"]},{"id":"webhook","g":"build","word":"Webhook","text":"Peteĩ marandu peteĩ sistema omondóva ijehegui ambuépe oiko pyaréve peteĩ mba'e, techapyrã “pago ojehupytýma”.","also":["webhooks"]},{"id":"library","g":"build","word":"Biblioteca","text":"Código oĩmbámava ambue tapicha ohaiva'ekue, ikatúva reiporu jey rehai rangue nde voi.","also":["libraries","bibliotecakuéra","library"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"Peteĩ estructura oĩmbámava ojejapo haguã app, odesidíva heta mba'e mba'éichapa oñemohenda pe código, peteĩ óga estructura remyenyhẽvaicha.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"Peteĩ caja tembiporu, código ha techapyrã reheve, ojejapo haguã software peteĩ plataforma térã servicio g̃uarã.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"Peteĩ biblioteca térã tembiporu nde código oikotevẽva ombaapo haguã. Iñimportante ojembopyahu tapiaite, seguridad rehehápe.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"Peteĩ aty código oĩmbámava ikatúva reinstala ha reiporu peteĩ tembiapópe.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"Peteĩ tembiporu ogueru ha ombopyahúva umi package nde código oikotevẽva. npm ha'e peteĩ ojeporuvéva.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Pe tembiporu ojeporuvéva oñeñongatu haguã código ñemoambue rembiasakue, commit ha branch ramo."},{"id":"github","g":"build","word":"GitHub","text":"Peteĩ web oñongatúva Git repo internet-pe, ikatu haguã atyhakuéra omboja'o código, ohecha ñemoambue ha osegi tembiapo."},{"id":"vcs","g":"build","word":"Version control","text":"Oñeñongatu opa ñemoambue rembiasakue umi archivo-pe, rehecha haguã máva omoambue mba'e ha rejevy haguã oikotevẽramo. Git ojapo upéva.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Rejapo nde copia entera peteĩ repo-gui, hembiasakue reheve, nde mba'e'oka-pe.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Regueru umi commit ipyahuvéva pe copia ojepurúvagui oñondive (GitHub-icha) nde mba'e'oka-pe. Push rovake.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"Pe código versión oficial opavave ombaapohápe, jepi oñehenóiva main térã master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"Mokõi ñemoambue opoko jave umi línea peteĩvare ambue ambue háicha, upévare mba'e'oka ndaikatúi ombojoaju ha peteĩ tapicha oiporavova'erã.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"Peteĩ jehecha ohechaukáva hekopete mba'épa oñemoambue mokõi versión pa'ũme: línea oñembojoapýva ha línea ojeipe'áva.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Nde copia peteĩ ambue tapicha repo-gui, ikatúva remoambue ojepoko'ỹre imba'évare.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"Peteĩ programa mbyky ojapóva peteĩ tembiapo ijehegui, techapyrã omohenda archivo térã omoñepyrũ pe app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Ojejapo pe código-gui peteĩ mba'e oĩmbáva oñembaapo haguã, térã pe resultado oĩmbáva voi.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Oñembohasa pe código tapichakuéra ohaíva peteĩ forma-pe mba'e'oka ikatúva omboguata voi.","also":["compiler"]},{"id":"cli","g":"build","word":"Línea de comando (CLI)","text":"Peteĩ ventana moñe'ẽrã rehaihápe instrucción mba'e'oka-pe g̃uarã, reikutu rangue. Oñehenói avei terminal.","also":["command line","command-line","CLI","terminal","línea de comando"]},{"id":"config","g":"build","word":"Ñemboheko (config)","text":"Umi ñemboheko omoakãva mba'éichapa oiko software, oñeñongatúva código-gui aparte, ikatu haguã ojemoambue ndahasýi.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Variable de entorno","text":"Peteĩ ñemboheko oñeme'ẽva peteĩ programa-pe oñepyrũ vove, jepi dirección térã ñe'ẽ ñemi g̃uarã, ani haguã ojehai código-pe.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Jeheka mba'érepa ndoikói peteĩ mba'e, ha oñemyatyrõ.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Mokõi tapicha (térã peteĩ tapicha ha peteĩ AI) ombaapo oñondive peteĩ código-pe, peteĩ ohai ha ambue ohecha.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentación (docs)","text":"Mombe'u ojehaíva mba'éichapa ombaapo peteĩ mba'e térã mba'éichapa ojeporu.","also":["documentation","docs","documentación"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Pe archivo peteĩha oñemoñe'ẽva peteĩ repo-pe: mba'épa pe tembiapo ha mba'éichapa ojemboguata.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"Peteĩ sistema ymaguare ojeporu gueteri ha hasy ojemoambue, jepi mbovymi tapicha oikuaa gueteri haguére.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Umi tape mbyky oñongatúva aravo ko'ág̃a ha katu ombotardéva ñemoambue upéi, peteĩ préstamo interés okakuaávaicha. Refactoring ohepyme'ẽ mbeguemi.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"Peteĩ prueba ohecha haguã peteĩ mba'e ombaapópa oikova'eráicha. Oĩ prueba mba'e'oka omboguatáva ijehegui código oñemoambue ñavõ; ambue ha'e nde reñeha'ãva peteĩ kuatia opámava reaceptá mboyve.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Quality assurance ñe'ẽ mbykýpe: opa mba'e ojejapóva ojehecha haguã pe tembiapo oĩ porãpa oho mboyve línea-pe. AI-gile-pe he'ise umi prueba automática: QA pytãramo, peteĩ mba'e ndoikói, ha ndaikatúi oho línea-pe oñemyatyrõ peve.","also":["jehechajey porã","quality checks"]},{"id":"testpile","g":"test","word":"Test aty","text":"Umi kuatia opámava oha'arõva reñeha'ã haguã, peteĩ peteĩ rire. Eguerohory peteĩ térã emondo jey peteĩ ñe'ẽ reheve, ha ou upe rire oúva.","also":["test pile","test piles"]},{"id":"autotest","g":"test","word":"Ñeha'ã automático","text":"Peteĩ prueba mba'e'oka ojapóva ijehegui código oñemoambue ñavõ, ojejuhu haguã jejavy pya'e.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Ñeha'ã manual","text":"Peteĩ tapicha oñeha'ã ipópe pe tembiapo, ohecha haguã oikópa oikova'eráicha.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"Peteĩ prueba automática michĩ, peteĩ código pehẽngue michĩmi año rehe.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"Peteĩ prueba ohecháva heta pehẽngue ombaapo porãpa oñondive, ndaha'éi peteĩteĩ añoite.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"Peteĩ prueba ojapóva peteĩ oiporúva añeteguaicha ñepyrũ guive opa peve, techapyrã oñeinscribi, ojogua ha ohepyme'ẽ.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"Umi tapicha ojeruréva pe tembiapo oñeha'ã ha'ekuéra voi ha he'i ojapópa mba'e oikotevẽva. AI-gile ñeha'ã aty ha'e iversión kóvagui.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Peteĩ mba'e ombaapo va'ekue ha oñembyai peteĩ ñemoambue rire. Regression test ohecha umi mba'e ymaguare ombaapo gueteripa.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"Peteĩ prueba pya'eterei ohecha haguã umi mba'e tenondegua ombaapópa, techapyrã peteĩ ñemoambue oĩ rire línea-pe. Ndoikóiramo, epyta ha ehecha.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Reñeha'ã pe producto rehe sãsõme ha rehecha heta háicha, rejuhu haguã problema umi prueba oñeplaneáva ohasaréitava.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"Peteĩ escenario ojehaíva reñeha'ã haguã: umi paso, ha mba'épa oikova'erã.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"Mboy código ohecha umi prueba automática. Hetave jepi hesegurove, ha katu coverage yvate año nohechaukái ombaapo porãha.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Marandu techapyrã ojeinventáva ojeporu haguã ñeha'ã aja, ani haguã ojehechauka tapicha añetegua marandu ñemi.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"Peteĩ situación ndajepiguáiva, rembe'ýpe oĩva, techapyrã peteĩ formulario nandi térã peteĩ téra apóstrofe reheve, jepi mba'e oñembyaihápe.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"Pe tape jepiguáva opa mba'e oho porãhápe. Ñeha'ã porã oñeha'ã avei umi tape ndoho porãihápe."},{"id":"perftest","g":"test","word":"Performance testing","text":"Ojehecha mba'eichaitépa ipya'e peteĩ mba'e ha mba'éichapa oaguanta ipohýi jave.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Ojehecha mba'éichapa oaguanta peteĩ sistema heta tapicha oiporu jave peteĩ jeýpe.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Ojeheka umi mba'e ikangýva ikatúva oheja peteĩvape oiporu vai peteĩ sistema térã ohecha umi mba'e ndohechava'erãva.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Ojehecha tapichakuéra ikatupyry ambuéva ikatúpa oiporu pe producto, avei lector de pantalla reheve térã teclado añoite reheve.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"Peteĩ prueba automática ohecháva jejavy ikatúva oĩ ha estilo oñemohenda'ỹva código-pe, peteĩ corrector ortográfico programa-kuéra g̃uarãicha.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Ojehecha código oĩpa problema, ojemoñe'ẽvo automáticamente, oñemboguata'ỹre.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"Peteĩ prueba sapy'ánte ohasa ha sapy'ánte ndohasái, mba'érepa ojekuaa'ỹre, upévare ndaikatúi ojerovia hese tuichaháicha.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Ojejapo jey peteĩ bug oiko, ojejapóvo umi paso peteĩchaguáva, ikatu haguã oñestudia ha oñemyatyrõ. Ojehai umi paso ha'e pe pehẽngue iporãvéva peteĩ bug marandu'ípe.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"Mba'eichaitépa ivai peteĩ problema ojapóva, mba'e michĩmi ombopochýva guive opa mba'e ojejoko peve.","also":["severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Ojekopia peteĩ versión pyahu software rehegua umi mba'e'oka omboguatávape, techapyrã peteĩ copia ñeha'ãrã térã pe servicio línea-pe oĩva."},{"id":"release","g":"change","word":"Ñemosẽ","text":"Peteĩ aty tembiapo opáva, héra reheve, oikéva línea-pe oñondive, ha ñe'ẽ mbykymi mba'épa oñemoambue. 🚀 Ñemosẽ ohai umi ñe'ẽ kuatia opámavagui.","also":["ñemosẽnguéra","release","releases"]},{"id":"rollback","g":"change","word":"Rollback","text":"Ojejevy pe versión paha ombaapova'ekuépe peteĩ pyahu ogueru jave problema. AI-gile-pe, Roll back ombyaty umi paso ojejevy haguã ojehaíva peteĩteĩ ñemoambuépe peteĩ checklist-pe.","also":["roll back","jevyjey"]},{"id":"live","g":"change","word":"Línea-pe","text":"Pe versión añetegua tapichakuéra oiporúva, ndaha'éi peteĩ kópia oñeha'ã haguã mba'e. Programador-kuéra ombohéra avei production.","also":["en vivo","production","producción"],"noTip":1},{"id":"change","g":"change","word":"Moambue","text":"Peteĩ moambue oñembosako'íva peteĩ mba'épe tapichakuéra oñeha'arõhápe, ojehaíva raẽ: mba'e, mba'ére, ñeha'ã, araka'e ha mba'éichapa ojehundíta. Eñepyrũ peteĩ 🔀 Ejerure moambue reheve.","also":["moambuekuéra","change request","cambio"],"noTip":1},{"id":"risk","g":"change","word":"Ñeha'ã","text":"Mba'e ikatúva ojavy, puntu reheve mba'eichaitépa ikatu oiko ha mba'eichaitépa ivaíta. ⚠️ Ñeha'ã oñongatu opavave peteĩ lista-pe, puntu yvateve raẽ, peteĩ teĩ ára reheve ojehecha jey haguã.","also":["riesgo","riesgos","risk","risk register"]},{"id":"chgwin","g":"change","word":"Moambue ovetã","text":"Umi aravo moambue ikatuhápe oike línea-pe, techapyrã peteĩ martes ka'aru kirirĩ. Ovetã okápe ndaikatúi oñemohu'ã peteĩ kuatia moambue rehegua, ndaha'éiramo emergencia.","also":["moambue ovetãnguéra","change window"]},{"id":"gonogo","g":"change","word":"Ñaha / Ndañahái","text":"Peteĩ jehecha paha peteĩ ñemoambue oho mboyve línea-pe: peteĩteĩ tapicha oaprobava'erã he'i Go térã No go. Oho tenonde opavave he'i jave Go añoite.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Ñemoneĩ","text":"Ha'arõ peteĩ héẽ tembiapo oñepyrũ mboyve. Peteĩ kuatia nde angirũ omoĩva, térã peteĩ moambue, oha'arõ ✅ Ñemoneĩ-pe remoneĩ térã rembotove peve.","also":["ñemoneĩnguéra","approval"]},{"id":"quiettime","g":"change","word":"Aravo py'a guapy","text":"Peteĩ aravo, techapyrã peteĩ live stream, peteĩ demo térã pyhare aja, mba'eve ndohoihápe línea-pe. Umi atyha osegi ombaapo ha oñeha'ã, ha katu oho haguã línea-pe oha'arõ opa peve. Ambue hendápe oñehenói change freeze.","also":["aravo py'a guapýpe","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Peteĩ tape ombaapo haguã, umi ojapóva software ha umi omboguatáva ombaapo peteĩ atyhaicha, heta automatización reheve, ikatu haguã ñemoambue oho línea-pe jepi ha seguro."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration ha delivery)","text":"Opavave ñemoambue ojembojoaju jepi main versión-pe ha ojehecha automáticamente peteĩteĩ jey (continuous integration), upévare pe software oĩmbá tapiaite oho haguã línea-pe peteĩ botón reikutúvo (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"Peteĩ paso mombyryve continuous delivery-gui: opa ñemoambue ohasáva umi prueba oho línea-pe ijehegui, ndaipóri botón reikutu haguã.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"Umi paso automático peteĩ ñemoambue ohasáva oho aja línea-pe, techapyrã build, test, upéi deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Entorno","text":"Peteĩ copia aparte pe sistema-gui peteĩ mba'e g̃uarã, techapyrã peteĩ ojemopu'ã haguã, peteĩ ojeha'ã haguã ha pe oĩva línea-pe.","also":["environments","entornokuéra","environment"],"noTip":1},{"id":"devenv","g":"change","word":"Entorno de desarrollo","text":"Pe copia peteĩ programador ombaapohápe, jepi imba'e'oka-pe, oñembyaíramo mba'e avave ndojehasa'asýi.","also":["dev environment","development environment"]},{"id":"testenv","g":"change","word":"Entorno de pruebas","text":"Peteĩ copia aparte pe sistema-gui ojeporúva ñeha'ã añoite g̃uarã, ani haguã ojepoko pe servicio añeteguáre.","also":["test environments","test environment"]},{"id":"staging","g":"change","word":"Staging","text":"Peteĩ copia paha oñemohendáva línea-pe oĩvaicha, ojehecha paha haguã peteĩ ñemoambue oho mboyve línea-pe.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"Pe archivo térã aty peteĩ build ojapóva, oĩmbáva oñeñongatu, ojehecha térã oñemoĩ haguã línea-pe.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"Peteĩ ñemyatyrõ urgente oñemoĩva pya'e línea-pe, plan jepiguáva okápe, oñembyai haguére peteĩ mba'e iñimportánteva.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"Peteĩ ñembopyahu michĩ omyatyrõva peteĩ bug térã omboty peteĩ kuára seguridad rehegua. Iñimportante oñemoĩ pya'e umi security patch.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Número de versión","text":"Peteĩ etiqueta 2.4.1-icha he'íva mba'e versión reguereko. Jepi pe papapy peteĩha oñemoambue ñemoambue tuichápe ha pe paha arreglo michĩme.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"Peteĩ lista mbyky ha hesakã mba'épa oñemoambue peteĩ versión-pe, umi oiporúvape g̃uarã, arreglo ha límite ojekuaáva reheve. Oñehenói avei changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"Peteĩ llave oñemyendy ha oñembogue peteĩ feature g̃uarã, ikatu haguã tembiapo pyahu oho línea-pe okañy ha oñemyendy (térã oñembogue jey) versión pyahu'ỹre.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Oñemyatyrõ peteĩ versión vai, ojemosẽvo pya'e peteĩ versión pyahu oñemyatyrõva, ojejevy rangue pe ymaguarépe.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Oñemoĩ peteĩ ñemoambue línea-pe peteĩ aty michĩme g̃uarã raẽ, ha opavavépe g̃uarã ojehecha rire oĩ porãha. Héra oúva canario-gui, umi minero ogueraha va'ekue yvy guýpe ohechauka haguã pya'e peligro.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Oñeñongatu mokõi copia pe sistema línea-pe oĩvagui ha ojehasa tapichakuérape pe pyahúpe peteĩ jeýpe, ikatu haguã rejevy pya'e oñembyaíramo.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Oñemoĩ peteĩ versión pyahu línea-pe, pe servicio opyta'ỹre araka'eve umi oiporúvape g̃uarã.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Ojeipytyvõ ñemoambue osẽ porã haguã: ojehecha pe riesgo, ojehupyty aprobación hekopegua ha ojeiporavo aravo porã. Oñehenói avei change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"Peteĩ aty ohecháva ñemoambue iñimportánteva ha odesidi ikatúpa oho tenonde ha araka'épa.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"Peteĩ ñemoambue riesgo michĩva, ojejapóva peteĩ tape ojeha'ãmavaicha jey ha jey, upévare oñeaprobáma raẽ.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"Peteĩ ñemoambue oikotevẽva ojehecha ha oñeaproba oho mboyve tenonde.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"Peteĩ ñemoambue oikova'erã pya'eterei omyatyrõ térã ojoko haguã peteĩ problema tuicha, aprobación pya'eve reheve.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automatización","text":"Ojejapo mba'e'oka ojapo ijehegui peteĩ tembiapo jey ha jey ojejapóva, upévare ipya'eve ha ojejapo peteĩcha tapiaite.","also":["automated","automation","automatizado"],"noTip":1},{"id":"infra","g":"change","word":"Infraestructura","text":"Umi máquina, red ha servicio software oñembaapohápe.","also":["infra","infrastructure"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Oñemombe'u nde servidor ha ñemboheko archivo-pe oñeñongatúva código ndive, ikatu haguã oñemopu'ã jey peteĩchaite tapiaite.","also":["IaC"]},{"id":"cloud","g":"change","word":"Nube","text":"Ojealquila mba'e'oka, ñongatuha ha servicio peteĩ empresa tuichávagui internet rupi, nde voi reguereko rangue umi máquina.","also":["the cloud","cloud computing","cloud"]},{"id":"provider","g":"change","word":"Cloud provider","text":"Peteĩ empresa oalquiláva computación internet rupi, techapyrã Amazon Web Services (AWS), Microsoft Azure térã Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Moõpa oĩ ha oñembaapo nde app térã web, ikatu haguã tapichakuéra oike hese, jepi ojealquiláva peteĩ empresa-gui."},{"id":"domain","g":"change","word":"Domain name","text":"Pe dirección web tapichakuéra ohaíva, techapyrã example.com. Ojealquila ary ary, upévare oñembopyahuva'erã.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Domain name system ñe'ẽ mbykýpe: internet agenda dirección rehegua, ombohasáva peteĩ téra example.com-icha pe mba'e'oka hekopeguáva dirección-pe.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"Peteĩ aty hambotypáva oguerekóva peteĩ app ha opa mba'e oikotevẽva, ombaapo haguã peteĩcha oimeraẽ mba'e'oka-pe. Docker ha'e pe tembiporu ojekuaavéva.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"Peteĩ mba'e'oka ojapo'ãva oikóva peteĩ mba'e'oka añetegua ryepýpe, ikatu haguã peteĩ máquina tuicha oiko hetaicha.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Oñemboguata código, nde voi reñangareko'ỹre servidor rehe: pe provider omboguata oikotevẽ jave ha rehepyme'ẽ reiporúva añoite."},{"id":"lb","g":"change","word":"Load balancer","text":"Peteĩ mba'e omboja'óva umi oikéva heta servidor-pe, ani haguã peteĩ año henyhẽterei.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"Peteĩ ñongatuha ag̃uiete oĩva resultado ipyahuvéva reheve, ani haguã ojeheka térã ojejapo jey pe mba'e peteĩcha. Ojemopotĩramo ikatu omyatyrõ página ojehechávo ymaguaréicha.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"Peteĩ servidor aty opa yvy rupi oguerekóva nde página ha ra'ãnga copia ag̃ui umi oikévagui, ojehupi haguã pya'e.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Ojegueraha dato térã sistema peteĩ ñemboheko ymaguarégui ipyahúvape, térã oñemoambue mbeguekatu mba'éichapa oñemohenda peteĩ base de datos.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Servicio","text":"Mba'e remopu'ãva'ekue tapichakuéra oñeha'arõva, peteĩ web térã app-icha, oñeñangarekóva oiko porã haguã. Emarka “Ko tembiapo ha'e peteĩ servicio” ha ere mba'épa ome'ẽ, máva oiporu ha máva on-call.","also":["servicios","service"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"Mboy aravo peteĩ servicio ombaapo, jepi porcentaje ramo. 99.9% oheja gueteri 43 minuto rupi ndoikói jasy ñavõ.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Uptime jehecha","text":"Peteĩ jehecha automático, sapy'a ha sapy'a, nde servicio ombohovái gueteri. Ojavýramo heta jey oñondive, AI-gile ojuruja ijehegui peteĩ kuatia incidente rehegua.","also":["uptime checks"]},{"id":"statuspage","g":"run","word":"Kuatiaha estado","text":"Peteĩ kuatiaha opavavépe g̃uarã ohechaukáva peteĩ servicio oikópa (hovy, naranja térã pytã) mombe'u ipyahuvéva reheve, umi oiporúva ikatu haguã ohecha oporandu rangue.","also":["status page","página de estado"]},{"id":"desk","g":"run","word":"Escritorio servicio rehegua","text":"Ko'ápe og̃uahẽ porandu ha marandu umi oiporúvagui nde servicio. AI-gile omoĩ peteĩ teĩ ñemoñe'ẽ, incidente térã ñemoĩ ramo, ha he'i ndéve ojoguáramo peteĩ mba'e oje'éma va'ekue.","also":["escritorio servicio rehegua-kuéra","mesa de ayuda","help desk"]},{"id":"svcrequest","g":"run","word":"Ñemoñe'ẽ servicio rehegua","text":"Peteĩ tapicha ojerure mba'e jepiguáva, peteĩ cuenta pyahu térã michĩmi pytyvõ-icha, he'i rangue oĩha mba'e oñembyaíva. Oha'arõ ijára; peteĩ incidente oho raẽ.","also":["ñemoñe'ẽ servicio rehegua-kuéra"]},{"id":"incident","g":"run","word":"Incidente","text":"Peteĩ mba'e oñembyaíva térã ndoikoporãiva umi oiporúvape g̃uarã ko'ag̃aite, techapyrã pe web ndoikói térã ipererĩeterei. Peteĩ kuatia 🔥 incidente ohasa umi ambue tenonde: ojejapo jey oiko haguã oho raẽ.","also":["incidentes","jejavy","incident"]},{"id":"major","g":"run","word":"Incidente guasu","text":"Peteĩ incidente tuicháva: heta tapicha ojehasa'asy, térã pirapire térã datos oĩ peligro-pe. Peteĩ botón omoĩ opavave atyha hese (swarm), omombáy pe on-call-pe ha ojerure peteĩ mombe'u estado rehegua 30 minuto peve.","also":["jejavy guasu","major incident"]},{"id":"oncall","g":"run","word":"On-call","text":"Ha'e pe ombohováiva mba'e oñembyai jave, pyharekuévo jepe. Peteĩ teĩ servicio oguereko peteĩ atyha rembiapo on-call oñemombáyva raẽ umi incidente rehe.","also":["on call","de guardia"]},{"id":"replyby","g":"run","word":"Aravo mbohovái","text":"Mboy aravo peteĩ kuatia ikatu oha'arõ mbohovái peteĩhápe, techapyrã peteĩ aravo peteĩ incidente-pe. Upe rire oguereko peteĩ aravopapaha pytã, ani haguã mba'eve oñehesarái kirirĩháme. Oñembohéra avei response target.","also":["response target","aravo mbohovái paha"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Peteĩ ma'ẽ mbykymi tapykuépe peteĩ incidente rire: mba'e oiko, mba'e oipytyvõ ha mba'e oñemoambueva'erã, ndojekulpáiva avavépe. Peteĩ incidente ndaikatúi oñemboty hese'ỹ.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Apañuái","text":"Pe mba'e kañymbyre oĩva peteĩ térã hetave incidente rapykuéri. Peteĩ kuatia 🧩 apañuái rehegua ombyaty umi incidente ou jeýva, ojejuhu ha oñemyatyrõ haguã pe ypykue opa ára g̃uarã.","also":["apañuáikuéra","problema","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Mba'e ypykue","text":"Pe mba'ére añetegua oñembyaihague, ndaha'éi pe rehecháva ojavy añoite. Emyatyrõ mba'e ypykue ha pe incidente nou jeýi.","also":["root cause","causa raíz"]},{"id":"workaround","g":"run","word":"Tape mbyky","text":"Peteĩ tape oiko porã haguã mba'e oĩ peve pe ñemyatyrõ añetegua, techapyrã emoñepyrũ jey peteĩ mba'e ojejokóramo. Ojehai pe kuatia apañuái rehegua-pe, ani haguã avave oheka jey.","also":["workaround","tape mbykykuéra"]},{"id":"knownerror","g":"run","word":"Jejavy ojekuaáva","text":"Peteĩ problema ojekuaáva mba'érepa oiko ha katu noñemyatyrõi gueteri, jepi peteĩ tape ambue ojehaíva reheve. 🧩 Known errors ohechauka chupekuéra, opavave oiporu haguã upe tape ambue ojeheka jey rangue.","also":["known error","known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Tembiapoukapy py'õ py'õ oñemyatyrõ haguã peteĩ apañuái ojekuaáva, ojejapo haguã peteĩchaite, pya'e, ára ha ára. Peteĩ incidente guasu rire atyha ikatu ome'ẽ ndéve peteĩ reme'ẽ haguã OK.","also":["runbooks"]},{"id":"ci","g":"run","word":"Mba'e ñemoĩrã","text":"Peteĩ mba'e nde servicio oñeha'arõva, servidor, dominio, certificado, llave térã proveedor-icha. 🗂️ Mba'e ñemoĩrã-kuéra ohechauka chupekuéra peteĩ teĩ servicio-pe, rehecha haguã mba'épa ojehecha peteĩ incidente rupi ha mba'épa oñembopyahu térã oñeñongatu va'erã backup-pe.","also":["mba'e ñemoĩrã-kuéra","elemento de configuración"]},{"id":"expiry","g":"run","word":"Ára opa haguã","text":"Pe ára peteĩ mba'e ndoikovéima oñembopyahu'ỹramo, techapyrã peteĩ web certificado de seguridad térã idirección web. AI-gile ohecha umi ára ha ojapo peteĩ kuatia oñembopyahu haguã peteĩteĩ 30 ára mboyve, ani haguã mba'eve opyta sapy'a.","also":["ára opa haguã-kuéra","vencimiento","ñemañe vencimiento rehe"]},{"id":"backup","g":"run","word":"Backup","text":"Peteĩ kópia oñeñongatúva nde datos-gui yma, reiporu haguã oñehundi térã oñembyaíramo mba'e. AI-gile ojapo ára ha ára peteĩ backup nde tablero-kuéragui.","also":["backups","back-up","copia de seguridad"]},{"id":"restore","g":"run","word":"Ñemoĩjey","text":"Emoĩ jey datos peteĩ backup-gui. Peteĩ backup ovale añete reikuaáramo ikatuha oñemoĩjey, upévare iporã reñeha'ã sapy'a ha sapy'a.","also":["emoĩjey","restore","restaurar"]},{"id":"svcreview","g":"run","word":"Ñehecha servicio rehegua","text":"Ñema'ẽ jey peteĩ servicio jasy peteĩme: incidente ojepe'a ha oñemyatyrõva, mba'eichapa pya'e tapichakuéra ohupyty mbohovái, uptime ha token ojeiporúva. Ñehecha jasy peteĩ ohechauka peteĩ teĩ servicio-pe g̃uarã.","also":["ñehecha servicio rehegua-kuéra","ñehecha jasy peteĩ","ñehecha jasy-kuéra"]},{"id":"accessreview","g":"run","word":"Ñehecha ñeike rehegua","text":"Ojehecha 90 ára ñavõ máva ikatu gueteri oike: link oñemboja'óva, angirũ rol ha ñe'ẽ ñemi ha llave oñeñongatúva. Reñongatu térã reipe'a peteĩteĩ, ani haguã acceso ymaguare opyta.","also":["ñehecha ñeike rehegua-kuéra"]},{"id":"improvements","g":"run","word":"Lista ñemoĩ porãve","text":"Opa mba'e atyha oiporavova'ekue oñemyatyrõ porãve haguã, peteĩ hendápe: retro ñemoĩ, ñehecha mba'e ha apañuái ñembohekopete, peteĩ teĩ iestado ndive. Ejuhu 📈 Ñemoĩ porãve-pe.","also":["lista ñemoĩ porãve-kuéra","ñemoĩ porãve"]},{"id":"tokencap","g":"run","word":"Token mba'ejoko","text":"Peteĩ mba'ejoko jasy g̃uarã umi token ikatúva oiporu peteĩ servicio agente-kuéra. 80%-pe og̃uahẽ ndéve peteĩ marandu; 100%-pe hembiapo kañymbyre oha'arõ ambue jasy peve térã rejupi peve mba'ejoko.","also":["token mba'ejoko-kuéra"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Opa mba'e oikotevẽva peteĩ servicio osegi haguã iporã ha ombaapo umi ojeroviávape hese g̃uarã, ára ha ára."},{"id":"itil","g":"run","word":"ITIL","text":"Peteĩ guía ojeporuvéva servicio ñangareko porã rehegua, oñe'ẽva incidente, problema ha ñemoambue rehe. Héra ymave he'ise IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Oñemboguata tecnología peteĩ servicioicha tapichakuérape g̃uarã, tape hesakãva reheve ojeatende haguã jerure, incidente, ñemoambue ha ñemyatyrõ.","also":["ITSM"]},{"id":"managed","g":"run","word":"Servicio administrado","text":"Peteĩ servicio ambue omboguata ha oñangarekóva ndéve g̃uarã, peteĩ acuerdo he'íva mba'eichaitépa ombaapova'erã.","also":["managed services","servicio administradokuéra"]},{"id":"svcowner","g":"run","word":"Servicio jára","text":"Pe tapicha ombohováiva peteĩ servicio entero rehe: mba'eichaitépa ombaapo, mboy hepy ha mba'éichapa oñemyatyrõve.","also":["service owners","servicio járakuéra"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"Peteĩ ñe'ẽme'ẽ ojehaíva clientekuérape mba'eichaitépa ombaapóta peteĩ servicio, techapyrã “oĩ 99.9% aravo” térã “ojehovái peteĩ aravo ryepýpe”, ha jepi pirapire ojevy ojejapo'ỹramo.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"Pe meta atyha voi omoĩva mba'eichaitépa ombaapova'erã peteĩ servicio peteĩ aravo pukukuépe, jepi michĩmi ipohýive SLA-gui, ani haguã oiko mba'evai.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"Pe medida añetegua rehecháva peteĩ meta ndive, techapyrã mboy visita-gui ojehupi porã.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Disponibilidad","text":"Tapichakuéra ikatúpa oiporu peteĩ servicio oikotevẽ jave, jepi ojeipapáva uptime ramo.","also":["high availability","disponibilidad yvate"]},{"id":"downtime","g":"run","word":"Downtime","text":"Aravo peteĩ servicio ndombaapóihápe térã oñembogue, oñeplaneáva térã nahániri.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"Pe jejavy michĩmi nde meta confiabilidad omoneĩva. Oĩ aja gueteri, ikatu reñeha'ã ñemoambue riesgo reheve; opa vove, reho mbeguevéta.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"Peteĩ aravo peteĩ servicio ndoikoihápe térã oñembyai vaieterei umi oiporúvape g̃uarã.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Ombaapo, ha katu vai: ipererĩ, térã oĩ pehẽngue ndombaapóiva.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Ojehecha peteĩ servicio automáticamente tapiaite, ojejuhu haguã problema, iporãvéramo umi oiporúva ohechakuaa mboyve."},{"id":"observability","g":"run","word":"Observability","text":"Mba'eichaitépa ikatu reikuaa mba'épa oiko peteĩ sistema ryepýpe okágui, umi log, papapy ha trace reheve.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"Peteĩ diario peteĩ programa ohaíva ojapo aja hembiapo, ojeporúva ojekuaa haguã mba'épa oho vai.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"Peteĩ registro mba'éichapa peteĩ jerure oguata peteĩ sistema pehẽngue rupi, paso ha paso, ohechaukáva moõpa oho mbegue.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"Mboy aravo oipe'a peteĩ mba'e ombohovái haguã, techapyrã reha'arõva reikutu guive pe página osẽ peve."},{"id":"alert","g":"run","word":"Alerta","text":"Peteĩ marandu automático he'íva peteĩ mba'e oikotevẽha jesareko, techapyrã pe web ndombohováiramo.","also":["alerts","alerting","alerta","alertakuéra"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"Oĩ jave hetaiterei alerta ha tapichakuéra oñepyrũ ndohecháivéma, avei umi iñimportánteva.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"Peteĩ pantalla ohechaukáva umi papapy ha estado iñimportantevéva peteĩ jehechápe.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Ojehenói pya'e térã ojepay pe tapicha oĩva guardia-pe peteĩ problema rehe.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Ojegueru peteĩ tapicha oguerekovéva katupyry térã autoridad, peteĩ problema ndaikatúi jave oñemyatyrõ ko nivel-pe, térã ndojejapói pya'e porã.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Oñemohenda pya'e umi problema oguahẽva mba'eichaitépa urgente ha iñimportante, ojeatende haguã raẽ pe ivaivéva.","also":["triaged"]},{"id":"impact","g":"run","word":"Impacto","text":"Mba'eichaitépa peteĩ mba'e ojehu tapichakuéra rehe: mboy tapicha, ha mba'eichaitépa ivai.","noTip":1},{"id":"urgency","g":"run","word":"Urgencia","text":"Mba'eichaitépa pya'e ojeatendeva'erã peteĩ mba'e. Impacto ha urgencia oñondive omoĩ prioridad.","noTip":1},{"id":"plevels","g":"run","word":"Nivel de prioridad (P1, P2…)","text":"Etiqueta he'íva mba'eichaitépa urgente peteĩ problema. P1 ha'e pe ivaivéva ha ojejapova'erã ko'ag̃aite voi.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket fila","text":"Pe lista jerure ha incidente oha'arõva peteĩva ogueraha.","also":["ticket queues","ticket filakuéra"]},{"id":"tiers","g":"run","word":"Primera línea ha segunda línea","text":"Pytyvõ nivel: primera línea ombohovái pe llamada ha omyatyrõ mba'e ndahasýiva; segunda línea oguereko katupyry pypukuve umi hasyvévape g̃uarã. Oñehenói avei tier 1 ha tier 2.","also":["first-line support","tier 1","tier 2","primera línea"]},{"id":"ic","g":"run","word":"Incident commander","text":"Pe tapicha año omoakãva mba'éichapa ojeatende peteĩ incidente, opavave oikuaa haguã máva odesidi ha máva ojapo mba'e.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"Mboy aravo ohasa peteĩva ogueraha mboyve peteĩ jerure térã incidente.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"Mboy aravo oipe'a oñemyatyrõmba haguã peteĩ jerure térã incidente, oñemomarandu guive oñemyatyrõ peve.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"Promedio-pe, mboy aravo oipe'a peteĩ servicio ombaapo jey haguã oñembyai rire. MTTR ikatu he'ise michĩmi ambue mba'e, upévare ere mba'épa reipapa.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"Promedio-pe, mboy aravo peteĩ servicio ombaapo peteĩ mba'e oñembyai mboyve.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"Pe lista opa nde configuration item ha mba'éichapa ojoaju, ikatu haguã rehecha mba'e odependeha mba'e rehe.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Oimeraẽ mba'e hepýva reguerekóva térã rehepyme'ẽva remboguata haguã pe servicio, techapyrã peteĩ laptop, peteĩ licencia software térã peteĩ dominio.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Ojehecha oĩtaha mba'e'oka pu'aka, ñongatuha ha tapicha hetaporã umi mba'e oúvape g̃uarã.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Ojeaguanta hetave oiporúva, oñeme'ẽvo peteĩ máquina-pe pu'aka hetave (scaling up) térã oñembojoapývo hetave máquina (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Umi plan osegi haguã umi mba'e iñimportantevéva peteĩ mba'e tuicha oho vai jave, techapyrã ojeperdévo peteĩ oficina, peteĩ proveedor tenondegua térã umi mba'e'oka.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"Pe plan ha tembiporu ojegueru jey haguã peteĩ servicio peteĩ mba'e vai tuicha rire, techapyrã ojeperdévo peteĩ data center entero.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"Pe aravo pukuvéva peteĩ servicio ikatúva opyta ndoikói peteĩ desastre rire, ombaapo jeyva'erã mboyve.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"Mboy dato ipyahúva ikatu reperde, ojeipapáva aravópe. Peteĩ RPO peteĩ aravo rehegua he'ise backup sa'ivéramo jepe aravo ñavõ.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancia","text":"Reguereko repuesto oĩmbáva, techapyrã peteĩ servidor mokõiha, ani haguã peteĩ falla ojoko pe servicio.","also":["redundancia"]},{"id":"failover","g":"run","word":"Failover","text":"Ojehasa ijehegui peteĩ sistema repuesto-pe pe jepiguáva oñembyai vove.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"Peteĩ pehẽngue oñembyaíva ha ogueraha opa mba'e hendive, ndaipóri haguére repuesto.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"Peteĩ aravo oñeplaneáva peteĩ servicio ikatuhápe opyta térã oho mbegue mantenimiento rehehápe, ojeikuaaukáva raẽ umi oiporúvape.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Oñembohasa tembiapo, kuaapy ha responsabilidad ambue tapicha térã atyhápe, ani haguã ho'a mba'eve.","also":["handovers"]},{"id":"kb","g":"run","word":"Knowledge base","text":"Peteĩ aty artículo ha ñembohovái pytyvõrã, umi oiporúva ha atyha g̃uarã.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"Peteĩ puntaje umi oiporúva ome'ẽva he'i haguã mba'eichaitépa ovy'a, jepi ojeporandúva peteĩ jerure oñemboty rire.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Proveedor","text":"Peteĩ empresa okaguáva rejeroviáva hese, techapyrã nde hosting provider. Oñehenói avei vendor térã third party.","also":["suppliers","vendor","vendors","third party","proveedorkuéra"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Oñembogue peteĩ servicio opa g̃uarã, seguro: ojeikuaauka umi oiporúvape, ojeatende idato ha acceso, ha opa umi gasto.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"Peteĩ producto ndohupytyvéima jave ñembopyahu térã pytyvõ ijapoharekuéragui, upévare oñemoambueva'erã ambuére.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Ciberseguridad","text":"Ojeñangareko sistema ha dato rehe, ani haguã oike hese oimeraẽ, ojemonda térã oñembyai.","also":["cyber security","ciberseguridad"]},{"id":"authn","g":"sec","word":"Autenticación (authentication)","text":"Ojehecha mávapa peteĩ tapicha, jepi peteĩ ñe'ẽ ñemi térã código reheve. Jepi oñembombykýva authn.","also":["authn","authentication","autenticación"]},{"id":"authz","g":"sec","word":"Autorización (authorisation)","text":"Ojehecha mba'épa ikatu ojapo peteĩ tapicha, ojekuaa rire mávapa. Jepi oñembombykýva authz.","also":["authz","authorization","authorisation","autorización"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Reike mokõi térã hetave prueba reheve, techapyrã nde ñe'ẽ ñemi ha peteĩ código oúva nde celular-pe. Oñehenói avei two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Reike peteĩ jey añoite ha upéicha reike heta sistema-pe, techapyrã reiporúvo nde cuenta tembiapo rehegua opa hendápe.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"Peteĩ app ojapóva ñe'ẽ ñemi hasy ojekuaa haguã ha imandu'a hesekuéra nde rehehápe.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"Peteĩ ñe'ẽ ñemi, llave térã ambue código ñemi peteĩ programa oiporúva oike haguã peteĩ mba'épe. Araka'eve ndojekompartiva'erã ni ndojehaiva'erã código-pe.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"Peteĩ código ñemi omoneĩva peteĩ programa-pe oiporu ambue servicio API, ha ohechaukáva mávapa oiporu (ha ohepyme'ẽ).","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"Peteĩ pase sapy'aguáva ohechaukáva peteĩ programa ikatuha oike, ani haguã oikotevẽ nde ñe'ẽ ñemi jey ha jey. Ndaha'éi peteĩcha peteĩ token AI rehegua ndive.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Cifrado (encryption)","text":"Oñembojeheregua marandu, ikatu haguã omoñe'ẽ pe oguerekóva llave hekopete añoite.","also":["encrypted","encrypt","encryption","cifrado"]},{"id":"https","g":"sec","word":"HTTPS","text":"Pe tape seguro página web oguatahápe, ojehechaukáva candado reheve nde navegador-pe, ani haguã avave mbytépe omoñe'ẽ térã omoambue chupekuéra."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"Peteĩ cédula digital omoneĩva peteĩ web-pe ohechauka mávapa ha'e ha oiporu HTTPS. Ovence, upévare oñembopyahuva'erã.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permisos","text":"Umi regla he'íva máva ikatu ohecha térã omoambue mba'e.","also":["permission","permisokuéra"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Oñeme'ẽ peteĩteĩ tapicha térã programa-pe pe acceso oikotevẽ añetéva añoite, ha oikotevẽ aja añoite.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Oñeme'ẽ acceso rol rupi, techapyrã omaña año térã oeditáva, ha ndaha'éi tapicha ha tapicha.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerabilidad (vulnerability)","text":"Peteĩ mba'e ikangýva oimeraẽva ikatúva oiporu oike haguã térã ojapo haguã mba'evai.","also":["vulnerabilities","vulnerabilidad"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"Peteĩ mba'e ikangýva umi atacante oikuaáva ijapoharekuéra ohupyty mboyve tiempo omyatyrõ haguã.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Software vai, techapyrã virus, ojejapóva ombyai, oespia térã omonda haguã."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware omboty nde archivo-kuéra ha ojerure pirapire oipe'a jey haguã. Backup porã ha'e pe defensa iporãvéva.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Marandu japu oñeha'ãva nembotavy reme'ẽ haguã nde ñe'ẽ ñemi térã pirapire, térã reipe'a haguã peteĩ mba'e vai.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Oñembotavy tapichakuérape, ndaha'éi mba'e'okápe, ome'ẽ haguã acceso, techapyrã peteĩ llamada japu “soporte técnico” rérape."},{"id":"firewall","g":"sec","word":"Firewall","text":"Peteĩ guardia odesidíva mba'e tráfico red-pe ikatu oike térã osẽ.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Virtual private network ñe'ẽ mbykýpe: peteĩ joaju privado ha cifrado internet rupi, jepi ojeporúva ojeike haguã seguro umi sistema tembiapo rehegua.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Ojemyenyhẽ peteĩ servicio tráfico japu hetaitereívare, tapicha añetegua ndaikatuvéi haguã oiporu. DDoS he'ise ou heta mba'e'okágui peteĩ jeýpe.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Ojekontrata experto ojeroviáva oñeha'ã haguã oike, ojejuhu haguã umi mba'e ikangýva umi atacante añetegua ojuhu mboyve.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"Peteĩ jehecha mbeguekatu mba'eichaitépa oñeñangareko peteĩ mba'ére, peteĩ lista práctica porã rehegua ndive.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Ojepensa porã máva ikatu oataka peteĩ mba'e, mba'éicha, ha mba'épa rejapóta rejoko haguã.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"Marandu ñemi osẽ jave umi ndoguerekova'erãvape, térã ojeperde térã ojemoambue permiso'ỹre.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Dato personal","text":"Oimeraẽ marandu peteĩ tapicha ikatúva ojekuaa rehegua, techapyrã héra, iemail térã moõpa oĩ. Oñehenói avei PII.","also":["PII","personally identifiable information","datokuéra personal"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Pe léi europea dato personal rehegua (Reino Unido oguereko iversión imba'éva): embyaty reikotevẽva añoite, eñongatu seguro, ha eheja tapichakuérape ohecha térã omboguete imba'ekuéra.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Ojeñangareko porã dato personal rehe ha léi he'iháicha.","also":["data protection law","protección de datos"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"Peteĩ página opavave ohecha haguã, he'íva mba'e dato personal rembyaty, mba'érepa, ha mba'épa rejapo hendive.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consentimiento","text":"Peteĩ tapicha “héẽ” hesakã ha sãsóva, imba'ekuéra ojeporu haguã peteĩ tape ojeikuaáva rupi. Ikatu oipe'a jey oimeraẽ aravo.","also":["opt-in","consentimiento"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"Peteĩ archivo michĩ peteĩ web oñongatúva nde navegador-pe imandu'a haguã mba'ére, techapyrã reikémaha. Oĩ oikotevẽva nde permiso raẽ.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Oñembyaty ha oñeñongatu umi dato personal reikotevẽ añetéva añoite pe tembiapo g̃uarã.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"Mboy aravo oñeñongatu peteĩ dato oñemboguete mboyve. Ani reñongatu oñeikotevẽvégui, hesegurove ha jepi léi he'i upéicha.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonimización","text":"Oñemoambue dato, ani haguã avave ikatu ojekuaa chugui.","also":["anonymised","anonymization","anonymous data","anonimización"]},{"id":"pseudo","g":"sec","word":"Pseudonimización","text":"Oñemoambue téra ha ambue detalle código rehe, ha oñeñongatu peteĩ llave aparte ikatu haguã ojoaju jey. Dato personal gueteri upéva.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"Peteĩ contrato he'íva mba'éichapa peteĩ proveedor ikatu oiporu dato personal nde rérape.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"Peteĩ jehecha mbeguekatu, reñepyrũ mboyve, mba'éichapa peteĩ plan oiporútava dato personal ikatu ojehu tapichakuéra rehe ha mba'éichapa oñemomichĩta umi riesgo.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"Peteĩ registro máva ojapo mba'e ha araka'e, ikatu haguã ojehecha jey upéi.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Rejapo umi léi, regla ha estándar he'íva ndéve, ha ikatu rehechauka rejapoha.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Peteĩ estándar internacional ojekuaaporãva oñeñangareko haguã marandu seguridad rehe. Umi empresa ikatu oñecertifica hese.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Peteĩ informe Estados Unidos-gua, auditor okaguáva ohecháva, ohechaukáva peteĩ empresa oñangarekoporãha cliente dato rehe.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"Peteĩ AI ombaapóva ijehegui peteĩ tembiapópe: omoñe'ẽ código, ojapo ñemoambue, omboguata prueba ha omombe'u ndéve. Hembiapo ojehecha gueteri.","also":["agents"]},{"id":"token","g":"ai","word":"Token","text":"Umi moñe'ẽrã pehẽngue michĩ AI omoñe'ẽ ha ohaíva, peteĩteĩ ha'e haimete ¾ peteĩ ñe'ẽgui. AI jeporu ojeipapa token-pe, upévare sa'ive token oheja hetave nde plan-gui.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Peteĩ comando michĩ oñemboguatáva ijehegui peteĩ momento ojeikuaávape, techapyrã peteĩ sesión AI oñepyrũ jave, ikatu haguã atyha ohendu nde ñe'ẽ.","also":["hooks"]},{"id":"ai","g":"ai","word":"Inteligencia artificial (AI)","text":"Umi sistema mba'e'oka rehegua ojapóva mba'e jajeroviáva oikotevẽha peteĩ tapicha, techapyrã ohai, ombohovái porandu térã ohechakuaa ra'ãnga.","also":["AI","IA","artificial intelligence","inteligencia artificial"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"Peteĩ tape ojeaprende haguã mba'e'oka umi patrón heta techapyrãgui, ndaha'éi oñeme'ẽvo chupe regla hekopete.","also":["machine learning"]},{"id":"model","g":"ai","word":"Modelo","text":"Pe “akã” entrenado peteĩ sistema AI rehegua, ojejapóva oaprende rupi hetaiterei techapyrãgui. Umi modelo ojoavy ikatupyry, ipya'e ha hepykuépe.","also":["models","AI model","modelokuéra"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"Peteĩ modelo AI entrenado hetaiterei moñe'ẽrã rehe, upévare ikatu omoñe'ẽ ha ohai ñe'ẽme.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI ojapóva mba'e pyahu, techapyrã moñe'ẽrã, ra'ãnga térã código, ndaha'éi omohenda térã ohechakuaa añoite.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Peteĩ programa reñomongetáva hendive ñe'ẽ jepiguáme, rehaívo térã reñe'ẽvo.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"Mba'e reme'ẽva AI-pe: nde porandu térã instrucción, ha oimeraẽ mba'e reme'ẽva chupe. Prompt hesakãvéva jepi ohupyty ñembohovái iporãvéva.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"Pe katupyry rehai haguã prompt ohupytýva resultado ojeroviakuaáva ha ipuruháva."},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Instrucción AI ohupytýva ñemongeta oñepyrũ mboyve, he'íva chupe mba'épa hembiapo ha mba'e regla osegiva'erã. Ipohýive umi rehaívagui.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Contexto","text":"Opa mba'e AI ikatúva ohecha ombaapo aja: instrucción, nde marandu, archivo omoñe'ẽva'ekue ha ñembohovái ymaguare.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"Mboy mba'e AI ikatu oñongatu iñakãme peteĩ jeýpe, ojeipapáva token-pe. Upéva rire, umi pehẽngue ymaguare ojepe'a térã oñembombyky.","also":["context windows"]},{"id":"session","g":"ai","word":"Sesión","text":"Peteĩ ñomongeta tembiapo rehegua AI ndive, ñepyrũ guive opa peve. Peteĩ sesión pyahu oñepyrũ mandu'a pyahu reheve.","also":["sessions","sesionkuéra","session"],"noTip":1},{"id":"memory","g":"ai","word":"Memoria","text":"Umi nota AI oñongatúva peteĩ sesión ha ambue pa'ũme, imandu'a haguã umi mba'e reipotavéva ha umi decisión ymaguare.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination (alucinación)","text":"AI he'i jave peteĩ mba'e ojehecha añeteguaicha ha katu ojeinventa térã ivaíva. Ehecha jey umi marandu iñimportánteva.","also":["hallucinations","hallucinate","hallucinates","alucinación"]},{"id":"training","g":"ai","word":"Entrenamiento","text":"Oñembo'e peteĩ modelo-pe, ojehechaukávo chupe hetaiterei techapyrã, oimeraẽva oiporu mboyve.","also":["trained","training","entrenado"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"Umi techapyrã peteĩ modelo oaprendeva'ekue. Ikuaapy opa pe ára umi dato oñembyatyrãme.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"Pe ára opahápe AI kuaapy ipype oĩva. Ndoikuaái umi mba'e upéi oikova'ekue, ndoheka'ỹramo.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Entrenamiento extra peteĩ modelo oĩmavavoi rehe, nde techapyrã reheve, ojapo porãve haguã peteĩ tembiapo ojeikuaáva.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"Peteĩ modelo AI ojeporu jave añetehápe ombohovái haguã peteĩ mba'e, ha ndaha'éi ojeentrena aja.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"AI ikatu jave ojapo mba'e, ndaha'éi oñe'ẽ añoite: omboguata comando, omoñe'ẽ archivo térã oheka web-pe, umi tembiporu pe app ome'ẽva chupe rupive.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"Peteĩ AI pytyvõhára, peteĩ AI tenondegua ome'ẽhápe peteĩ tembiapo michĩve, ha upéi ohupyty chugui pe resultado.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Heta AI ombaapo oñondive peteĩ tembiapópe, peteĩteĩ ipehẽngue reheve, peteĩ atyha michĩicha.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomía","text":"Mba'eichaitépa AI ikatu ojapo ijehegui oporandu mboyve peteĩ tapichápe.","also":["autonomous","autonomía"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Peteĩ tapicha osegi oĩ ohecha térã oaproba haguã mba'épa ojapo AI umi momento iñimportantevévape. AI-gile-pe upéva ha'e nde.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Límite ha jehecha omantenéva AI rembiapo seguro, techapyrã oikotevẽ aprobación oho mboyve mba'eve línea-pe. Omomichĩ jejavy riesgo, ha katu nomboykemo'ãi enteramente.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Oñeheja AI oheka nde kuatia-kuérape ombohovái mboyve, ikatu haguã iñembohovái oñemopyenda nde marandu añeteguáre.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Oñembohasa moñe'ẽrã peteĩ lista papapy-pe oñongatúva he'iséva, ikatu haguã mba'e'oka ojuhu umi mba'e he'iséva ojoguaitéva.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"Peteĩ base de datos ojejapóva oheka haguã umi lista papapy (embedding), ojuhu haguã marandu he'iséva ojoguáva.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Peteĩ tape ojeporuvéva oñemoinge haguã tembiporu ha dato AI app-pe, ikatu haguã AI oiporu.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperatura","text":"Peteĩ ñemboheko he'íva mba'eichaitépa iñaventurero AI ñembohovái. Michĩramo, ñembohovái hekojojave ha ojekuaa porãvéva; yvateramo, ojoavyve. Ni peteĩva ndojapói hekopete tapiaite.","also":["model temperature","temperatura"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Ikatúva ombaapo peteĩ marandu ñemohenda ndive ha hetave, techapyrã moñe'ẽrã, ra'ãnga ha ruido.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluación (eval)","text":"Peteĩ prueba oñeplaneáva mba'eichaitépa AI ojapo porã umi techapyrã oñeiporavóvape, ikatu haguã ojejogueraha modelo térã prompt.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Sesgo","text":"AI (térã peteĩ tapicha) oñesũ jave hekope'ỹme peteĩ gotyo, jepi umi mba'e oaprendeva'ekuégui.","also":["biased","bias","sesgo"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Ojeporu AI hekojojápe, seguro ha añetéme, ha tapichakuéra ombohovái gueteri umi resultado rehe.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"Peteĩ ñembotavy, umi instrucción okañýva peteĩ página web térã archivo-pe oñeha'ãhápe ojapouka AI-pe peteĩ mba'e oiporúva ndojeruréiva.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"Peteĩ límite mboy jerure ikatu remondo peteĩ servicio-pe peteĩ aravo ojeikuaávape. Rehasáramo, reha'arõva'erã.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"Mboy tembiapo AI rehegua nde plan omoneĩ peteĩ aravo pukukuépe; upéi opyta térã hepyve.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Ojejapo software, heta jey remombe'úvo AI-pe mba'épa reipota ha reheja chupe ohai pe código.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Presupuesto","text":"Pe pirapire oñemoĩva peteĩ mba'e g̃uarã.","also":["budgets","presupuestokuéra"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"Pe ñemoha'ãnga iporãvéva mboýpa hepýta peteĩ mba'e reñepyrũ mboyve.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"Mba'épa rehupyty jey, ojejogueraháva remoĩva'ekue ndive. Positivo ramo, ovale.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Opa mba'e peteĩ mba'e hepy añetéva hekove pukukue javeve, ndaha'éi hepykue rejoguávo añoite: omboguata, soporte, ñembopyahu ha ipahápe oñembogue.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx ha OpEx","text":"CapEx ha'e pirapire ojegastáva ñepyrũme umi mba'e reñongatútava rehe; OpEx ha'e gasto osegíva, techapyrã umi factura jasy ñavõ.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Suscripción","text":"Rehepyme'ẽ jepi, jasy térã ary ñavõ, reiporu haguã gueteri peteĩ mba'e.","also":["subscriptions","suscripciónkuéra"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software reiporúva internet rupi ha rehepyme'ẽva suscripción rupi, ha ijapohára omboguata ndéve g̃uarã.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Rehepyme'ẽ reiporúva añoite, techapyrã cloud computing térã AI token.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Jeporu nde plan oguerekóvagui hetave, ikatúva hepyve.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"Peteĩ marandu oúva gasto térã jeporu oguahẽ jave peteĩ nivel reiporavova'ekuépe. Ndeavisa, ha katu ndojokói tapiaite umi cobro oúva.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"Peteĩ nivel sãso peteĩ servicio rehepyme'ẽvagui, límite reheve. Iporã reñepyrũ haguã.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"Umi paquete peteĩ servicio ovendéva, peteĩteĩ ijepy ha ilímite reheve.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licencia","text":"Umi regla he'íva mba'éichapa ikatu reiporu, rekopia, remoambue térã remboja'o peteĩ mba'e ambue ojapova'ekue, techapyrã software, letra térã ra'ãnga.","also":["licences","license","licenses","licencia"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software oimeraẽva ikatuhápe omoñe'ẽ ikódigo, oiporu ha jepi omoambue rei, ilicencia regla he'iháicha.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Licencia open source","text":"Umi regla oúva código open source ndive. Oĩ ndeheja rejapo haguã haimete opa mba'e (techapyrã MIT); oĩ ojerure ndéve remboja'o avei nde ñemoambue (techapyrã GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Propietario (Proprietary)","text":"Peteĩ empresa mba'e ha ndaikatúi rekopia térã remoambue rei. Open source rovake.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"Pe derecho legal peteĩ apohára oguerekóva odesidi haguã umi copia hembiapo rehegua, avei código ha jehai.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Propiedad intelectual (IP)","text":"Idea ha mba'e ojejapóva léi ohecháva oguerekoha ijára, techapyrã código, diseño, téra ha logo.","also":["intellectual property","propiedad intelectual"]},{"id":"tos","g":"money","word":"Términos de servicio","text":"Umi regla remoneĩva reiporúvo peteĩ servicio.","also":["terms and conditions","terms of use","terms of service","términos y condiciones"]},{"id":"contract","g":"money","word":"Contrato","text":"Peteĩ acuerdo ojehaíva mokõi lado pa'ũme ha léi omomba'éva.","also":["contracts","contratokuéra"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"Peteĩ kuatia he'íva hekopete mba'e tembiapo ojejapóta, araka'e peve ha mboýpe.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"Peteĩ hepy oñemoneĩva tembiapo entero rehe, taha'e ha'éva mboy aravo oipe'a.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Rehepyme'ẽ umi aravo ojeba'apo añetehápe ha umi mba'e ojeporu añetehápe, ndaha'éi peteĩ hepy oñemoĩmbáva.","also":["T&M"]},{"id":"invoice","g":"money","word":"Factura","text":"Peteĩ kuatia ojeruréva pago peteĩ tembiapo ojejapova'ekue térã mba'e oñeme'ẽva'ekue rehe.","also":["invoices","facturakuéra"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"Hasy térã hepyeterei jave reho peteĩ proveedor-gui, ha upévare repyta hendive.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"Pe proceso ojeiporavo ha ojejoguahápe proveedor-gui."},{"id":"servicecredit","g":"money","word":"Service credit","text":"Pirapire ojevýva térã descuento rehupytýva peteĩ proveedor ndojapóiramo pe SLA he'íva.","also":["service credits"]}]}};
